CREATE OR REPLACE FUNCTION private.accept_practice_invitation(p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    invitation private.practice_invitations;
    member public.practice_memberships;
    actor uuid := auth.uid();
begin
    if actor is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text,0));
    select * into invitation from private.practice_invitations where token_digest=p_token_digest;
    if not found then return '{"status":"invalid-invitation"}'::jsonb; end if;
    perform 1 from public.practices where id=invitation.practice_id for update;
    invitation := private.invitation_for_actor(p_token_digest);
    if invitation.id is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    select * into member from public.practice_memberships where user_id=actor and state='active';
    if found then
        if member.practice_id <> invitation.practice_id then return '{"status":"other-practice"}'::jsonb; end if;
        return pg_catalog.jsonb_build_object('status','already-member','practiceId',member.practice_id,'role',member.role);
    end if;
    if invitation.state <> 'pending' then return '{"status":"invalid-invitation"}'::jsonb; end if;
    insert into public.practice_memberships (practice_id,user_id,role)
    values(invitation.practice_id,actor,invitation.role)
    on conflict(practice_id,user_id) do update set role=excluded.role,state='active',
        version=practice_memberships.version+1,updated_at=pg_catalog.clock_timestamp()
    returning * into member;
    update private.practice_invitations set state='accepted',accepted_user_id=actor,
        accepted_at=pg_catalog.clock_timestamp(),version=version+1,updated_at=pg_catalog.clock_timestamp()
    where id=invitation.id;
    return pg_catalog.jsonb_build_object('status','success','practiceId',member.practice_id,'role',member.role);
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_credential_change(p_practice_id uuid, p_request_id uuid, p_credential_id uuid, p_expected_version integer, p_expected_cycle_id uuid, p_expected_date_revision integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    credential public.credentials;
    cycle public.credential_cycles;
    operation text := case when p_values is null then 'credential-archived' else 'credential-updated' end;
    payload jsonb;
    result jsonb;
    before_data jsonb;
    covered uuid[];
    old_covered uuid[];
    date_changed boolean;
    changed boolean;
    next_record_number text;
begin
    if p_request_id is null or p_credential_id is null or p_expected_cycle_id is null
       or p_expected_version is null or p_expected_version < 1
       or p_expected_date_revision is null or p_expected_date_revision < 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if p_values ? 'status' then return p_values; end if;
    payload := pg_catalog.jsonb_build_object('contract_version', 1, 'operation', operation,
        'credential_id', p_credential_id, 'expected_version', p_expected_version,
        'expected_cycle_id', p_expected_cycle_id, 'expected_date_revision', p_expected_date_revision,
        'values', p_values);
    result := private.register_change_replay(p_practice_id, p_request_id, operation, payload);
    if result is not null then return result; end if;
    select * into credential from public.credentials
    where practice_id = p_practice_id and id = p_credential_id;
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    cycle := private.current_credential_cycle(p_practice_id, credential.id);
    if credential.archived_at is not null then return '{"status":"archived"}'::jsonb; end if;
    if p_values is not null and cycle.completed_at is not null then return '{"status":"completed"}'::jsonb; end if;
    before_data := private.credential_maintenance_projection(credential);
    if credential.version <> p_expected_version or cycle.id <> p_expected_cycle_id
       or cycle.date_revision <> p_expected_date_revision then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', before_data);
    end if;
    changed := true;
    date_changed := false;
    if p_values is not null then
        next_record_number := case when p_values ? 'record_number' then p_values->>'record_number'
            when credential.type is distinct from p_values->>'type' then null
            else credential.record_number end;
        select coalesce(array_agg(x::uuid order by x::uuid), '{}'::uuid[]) into covered
        from pg_catalog.jsonb_array_elements_text(p_values->'covered_clinician_ids') x;
        if ((p_values->>'owner_clinician_id') is not null and not exists (
            select 1 from public.clinicians where practice_id = p_practice_id
                and id = (p_values->>'owner_clinician_id')::uuid
        )) or exists (select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )) then return '{"status":"invalid-reference"}'::jsonb; end if;
        select coalesce(array_agg(clinician_id order by clinician_id), '{}'::uuid[]) into old_covered
        from public.policy_coverage where practice_id = p_practice_id and credential_id = credential.id;
        date_changed := cycle.end_date is distinct from (p_values->>'end_date')::date
            or cycle.action_deadline is distinct from (p_values->>'action_deadline')::date;
        changed := date_changed or credential.title is distinct from p_values->>'title'
            or credential.type is distinct from p_values->>'type'
            or credential.owner_kind is distinct from p_values->>'owner_kind'
            or credential.owner_clinician_id is distinct from (p_values->>'owner_clinician_id')::uuid
            or credential.issuer is distinct from p_values->>'issuer'
            or credential.jurisdiction is distinct from p_values->>'jurisdiction'
            or old_covered is distinct from covered
            or credential.record_number is distinct from next_record_number;
    end if;
    if changed and (credential.version = 2147483647 or (date_changed and cycle.date_revision = 2147483647)) then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', before_data);
    end if;
    if changed then
        if p_values is null then
            update public.credentials set archived_at = pg_catalog.clock_timestamp(),
                version = version + 1, updated_at = pg_catalog.clock_timestamp()
            where practice_id = p_practice_id and id = credential.id returning * into credential;
        else
            delete from public.policy_coverage where practice_id = p_practice_id and credential_id = credential.id;
            update public.credentials set title = p_values->>'title', type = p_values->>'type',
                owner_kind = p_values->>'owner_kind', owner_clinician_id = (p_values->>'owner_clinician_id')::uuid,
                issuer = p_values->>'issuer', jurisdiction = p_values->>'jurisdiction',
                record_number = next_record_number,
                version = version + 1, updated_at = pg_catalog.clock_timestamp()
            where practice_id = p_practice_id and id = credential.id returning * into credential;
            insert into public.policy_coverage (practice_id, credential_id, clinician_id)
            select p_practice_id, credential.id, x from unnest(covered) x;
            if date_changed then
                update public.credential_cycles set end_date = (p_values->>'end_date')::date,
                    action_deadline = (p_values->>'action_deadline')::date,
                    date_revision = date_revision + 1, updated_at = pg_catalog.clock_timestamp()
                where practice_id = p_practice_id and id = cycle.id;
            end if;
        end if;
    end if;
    result := pg_catalog.jsonb_build_object('status', 'success', 'changed', changed,
        'credential', private.credential_maintenance_projection(credential));
    if changed and (date_changed or p_values is null) then
        perform private.dirty_email_reminders(p_practice_id, operation, p_credential_id);
    end if;
    return private.finish_register_change(p_practice_id, p_request_id, credential.id, operation,
        payload, before_data, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_email_reminder_event(p_namespace text, p_event_id text, p_provider_id uuid, p_attempt_id uuid, p_status text, p_from text, p_to text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
 SET lock_timeout TO '1s'
AS $function$
declare attempt private.reminder_message_attempts; endpoint private.reminder_email_endpoints;
    existing private.reminder_delivery_events; anomaly boolean; row record;
begin
    if p_status is null or p_status not in ('sent','delivered','delayed','bounced','complained','failed','suppressed')
        or p_event_id is null or char_length(p_event_id) not between 1 and 256 then return '{"status":"invalid"}'::jsonb; end if;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id and provider_kind = 'resend' and provider_namespace = p_namespace;
    if not found then return '{"status":"unavailable"}'::jsonb; end if;
    select * into endpoint from private.reminder_email_endpoints where id = attempt.endpoint_id for update;
    -- Suppression locks endpoint then matching jobs in a fixed order; no domain/Auth locks.
    if p_status in ('bounced','complained','suppressed') then
        perform id from private.reminder_jobs where endpoint_id = endpoint.id order by id for update;
    else perform 1 from private.reminder_jobs where id = attempt.job_id for update; end if;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id for update;
    if attempt.payload->>'from' is distinct from p_from or attempt.payload->'to' <> jsonb_build_array(p_to)
        or p_provider_id is null or (attempt.provider_id is not null and attempt.provider_id <> p_provider_id)
        or (attempt.provider_id is null and attempt.outcome not in ('submitting','uncertain')) then return '{"status":"conflict"}'::jsonb; end if;
    select * into existing from private.reminder_delivery_events where provider_namespace = p_namespace and event_id = p_event_id;
    if found then
        if existing.attempt_id <> attempt.id or existing.provider_id <> p_provider_id or existing.status <> p_status then
            return '{"status":"conflict"}'::jsonb;
        end if;
        return '{"status":"recorded"}'::jsonb;
    end if;
    anomaly := attempt.delivery in ('delivered','bounced','complained','failed','suppressed') and attempt.delivery <> p_status;
    insert into private.reminder_delivery_events (provider_namespace, event_id, practice_id, attempt_id, provider_id, status, anomaly)
    values (p_namespace, p_event_id, attempt.practice_id, attempt.id, p_provider_id, p_status, coalesce(anomaly, false));
    update private.reminder_message_attempts set provider_id = p_provider_id,
        outcome = case when outcome in ('submitting','uncertain') then 'accepted' else outcome end,
        delivery = private.email_delivery_state(delivery,p_status) where id = attempt.id;
    update private.reminder_jobs set state = 'accepted', updated_at = clock_timestamp()
        where id = attempt.job_id and state in ('submitting','uncertain');
    if p_status in ('bounced','complained','suppressed') then
        update private.reminder_email_endpoints set suppressed = true,
            epoch = epoch + case when suppressed then 0 else 1 end,
            reason = case when reason = 'complained' then reason else p_status end where id = endpoint.id;
        update private.reminder_message_attempts set check_due=null,recovery_version=recovery_version+1
            where endpoint_id=endpoint.id and check_due is not null;
        with canceled as (
            update private.reminder_jobs set state = 'suppressed', reason = 'email-suppressed', claim_token = null,
                claim_until = null, invalidated_at = clock_timestamp(), updated_at = clock_timestamp()
            where endpoint_id = endpoint.id and state in ('blocked','queued','claimed') returning practice_id, id
        ) insert into private.reminder_job_events (practice_id, job_id, operation)
            select practice_id, id, 'email-suppressed' from canceled;
    end if;
    return '{"status":"recorded"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_renewal_change(p_practice_id uuid, p_request_id uuid, p_credential_id uuid, p_expected_version integer, p_expected_cycle_id uuid, p_expected_date_revision integer, p_expected_renewal_version integer, p_intent text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare credential public.credentials; cycle public.credential_cycles;
    link private.credential_renewal_links; workflow private.credential_renewal_workflows;
    receipt private.renewal_change_requests; payload jsonb; result jsonb; before_data jsonb;
    current_data jsonb; normalized text; resource_version integer; changed boolean;
    occurred timestamptz; next_status text; next_ack timestamptz; next_actor uuid;
begin
    perform private.require_register_member(p_practice_id, true);
    if p_request_id is null or p_credential_id is null or p_expected_cycle_id is null
        or p_expected_version is null or p_expected_version < 1
        or p_expected_date_revision is null or p_expected_date_revision < 1
        or p_expected_renewal_version is null or p_expected_renewal_version < 1
        or p_intent is null or p_intent not in ('link', 'progress', 'review') then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if p_intent = 'link' then
        begin normalized := private.renewal_url(p_value);
        exception when invalid_parameter_value then
            return '{"status":"invalid","errors":{"url":"Enter a valid HTTPS renewal link (up to 2,048 characters)."}}'::jsonb;
        end;
    elsif p_intent = 'progress' then
        if p_value is null or p_value not in ('not-started', 'in-progress', 'awaiting-approval') then
            return '{"status":"invalid","errors":{"progress":"Choose a renewal progress status."}}'::jsonb;
        end if;
        normalized := p_value;
    end if;
    payload := pg_catalog.jsonb_build_object('intent', p_intent, 'credentialId', p_credential_id,
        'expectedVersion', p_expected_version, 'expectedCycleId', p_expected_cycle_id,
        'expectedDateRevision', p_expected_date_revision,
        'expectedRenewalVersion', p_expected_renewal_version, 'value', normalized);
    select * into receipt from private.renewal_change_requests
    where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id;
    if found then
        if receipt.intent <> p_intent or receipt.payload <> payload then
            return '{"status":"request-conflict"}'::jsonb;
        end if;
        return receipt.result;
    end if;
    select * into credential from public.credentials where practice_id = p_practice_id and id = p_credential_id;
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    cycle := private.current_credential_cycle(p_practice_id, credential.id);
    if credential.archived_at is not null then return '{"status":"archived"}'::jsonb; end if;
    if cycle.completed_at is not null then return '{"status":"completed"}'::jsonb; end if;
    before_data := private.renewal_projection(credential);
    current_data := private.credential_maintenance_projection(credential)
        || pg_catalog.jsonb_build_object('renewal', before_data);
    resource_version := (before_data->case when p_intent = 'link' then 'link' else 'workflow' end->>'version')::integer;
    if credential.version <> p_expected_version or cycle.id <> p_expected_cycle_id
        or cycle.date_revision <> p_expected_date_revision or resource_version <> p_expected_renewal_version then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', current_data);
    end if;
    select * into link from private.credential_renewal_links
    where practice_id = p_practice_id and credential_id = credential.id;
    select * into workflow from private.credential_renewal_workflows
    where practice_id = p_practice_id and cycle_id = cycle.id;
    changed := case when p_intent = 'link' then link.url is distinct from normalized
        when p_intent = 'progress' then coalesce(workflow.status, 'not-started') <> normalized
        else workflow.acknowledged_at is null end;
    if changed and resource_version = 2147483647 then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', current_data);
    end if;
    if changed then
        occurred := pg_catalog.clock_timestamp();
        if p_intent = 'link' then
            insert into private.credential_renewal_links (practice_id, credential_id, url, version, created_at, updated_at)
            values (p_practice_id, credential.id, normalized, resource_version + 1, occurred, occurred)
            on conflict (practice_id, credential_id) do update
                set url = excluded.url, version = excluded.version, updated_at = excluded.updated_at;
        else
            next_status := case when p_intent = 'progress' then normalized else coalesce(workflow.status, 'not-started') end;
            next_ack := case when p_intent = 'review' then occurred else workflow.acknowledged_at end;
            next_actor := case when p_intent = 'review' then auth.uid() else workflow.acknowledged_by end;
            insert into private.credential_renewal_workflows
                (practice_id, cycle_id, status, version, acknowledged_at, acknowledged_by, created_at, updated_at)
            values (p_practice_id, cycle.id, next_status, resource_version + 1, next_ack, next_actor, occurred, occurred)
            on conflict (practice_id, cycle_id) do update set status = excluded.status,
                version = excluded.version, acknowledged_at = excluded.acknowledged_at,
                acknowledged_by = excluded.acknowledged_by, updated_at = excluded.updated_at;
        end if;
        insert into private.renewal_audit_events
            (practice_id, actor_user_id, credential_id, cycle_id, operation, before_data, after_data, occurred_at)
        values (p_practice_id, auth.uid(), credential.id, cycle.id,
            case when p_intent = 'link' then 'link-changed' when p_intent = 'progress' then 'progress-changed' else 'review-acknowledged' end,
            before_data, private.renewal_projection(credential), occurred);
    end if;
    result := pg_catalog.jsonb_build_object('status', 'success', 'changed', changed,
        'credential', private.credential_maintenance_projection(credential)
            || pg_catalog.jsonb_build_object('renewal', private.renewal_projection(credential)));
    insert into private.renewal_change_requests
        (practice_id, actor_user_id, request_id, credential_id, cycle_id, intent, payload, result)
    values (p_practice_id, auth.uid(), p_request_id, credential.id, cycle.id, p_intent, payload, result);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_sms_provider_opt_out(p_account_sid text, p_messaging_service_sid text, p_phone text, p_message_sid text, p_opt_out_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare endpoint private.sms_phone_endpoints; event private.sms_provider_events;
begin
    if p_opt_out_type is null or p_opt_out_type not in ('STOP','START','HELP') or p_message_sid is null or p_message_sid !~ '^SM[0-9a-fA-F]{32}$' then raise exception 'Invalid event' using errcode='23514'; end if;
    insert into private.sms_phone_endpoints (account_sid,messaging_service_sid,phone_e164) values (p_account_sid,p_messaging_service_sid,p_phone) on conflict do nothing;
    select * into endpoint from private.sms_phone_endpoints where account_sid=p_account_sid and messaging_service_sid=p_messaging_service_sid and phone_e164=p_phone for update;
    select * into event from private.sms_provider_events where account_sid=p_account_sid and message_sid=p_message_sid;
    if found then
        if event.endpoint_id<>endpoint.id or event.opt_out_type<>p_opt_out_type then return '{"status":"conflict"}'::jsonb; end if;
        return '{"status":"success"}'::jsonb;
    end if;
    insert into private.sms_provider_events (account_sid,message_sid,endpoint_id,opt_out_type) values (p_account_sid,p_message_sid,endpoint.id,p_opt_out_type);
    if p_opt_out_type='STOP' then update private.sms_phone_endpoints set provider_blocked=true,suppression_epoch=suppression_epoch+1 where id=endpoint.id; end if;
    return '{"status":"success"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.authorize_renewal_evidence_download(p_practice_id uuid, p_actor_id uuid, p_credential_id uuid, p_cycle_id uuid, p_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence private.renewal_evidence; object private.renewal_evidence_objects; access_id uuid;
begin
    perform private.require_evidence_actor(p_practice_id, p_actor_id, false);
    select * into evidence from private.renewal_evidence where practice_id = p_practice_id
        and credential_id = p_credential_id and cycle_id = p_cycle_id and id = p_evidence_id and state = 'available';
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    select * into object from private.renewal_evidence_objects where evidence_id = evidence.id and state = 'verified';
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    access_id := private.evidence_event(evidence, p_actor_id, 'download-authorized');
    return jsonb_build_object('status', 'download', 'accessId', access_id, 'path', object.object_path,
        'filename', evidence.filename, 'mime', evidence.mime, 'byteCount', evidence.byte_count, 'digest', evidence.digest);
end;
$function$

CREATE OR REPLACE FUNCTION private.begin_email_recovery_at(p_job_id uuid, p_token uuid, p_config jsonb, p_kind text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare job private.reminder_jobs; a private.reminder_message_attempts; endpoint private.reminder_email_endpoints;
    context jsonb; permission jsonb; reservation private.reminder_email_submissions; urgency text;
begin
    if p_kind='fresh' then
        permission:=private.begin_email_reminder_at(p_job_id,p_token,p_config,p_now);
        if permission->>'status'<>'submit' then return permission; end if;
        select * into a from private.reminder_message_attempts where id=(permission->>'attemptId')::uuid for update;
        select * into job from private.reminder_jobs where id=p_job_id;
        update private.reminder_message_attempts set recovery_state='submitting',post_count=1,
            retry_expires=p_now+interval '23 hours',app_origin=p_config->>'appUrl',
            urgency=case when job.due_date < (p_now at time zone job.timezone)::date then 'past-due'
                when job.due_date = (p_now at time zone job.timezone)::date then 'today' else 'future' end
        where id=a.id returning * into a;
    elsif p_kind='retry' then
        if exists(select 1 from private.gmail_reminder_authority where enabled) then return '{"status":"unavailable"}'; end if;
        select * into job from private.reminder_jobs where id=p_job_id;
        if not found or not private.lock_email_recipient(job.practice_id) then return '{"status":"unavailable"}'; end if;
        select * into endpoint from private.reminder_email_endpoints where id=job.endpoint_id for update nowait;
        select * into job from private.reminder_jobs where id=p_job_id for update nowait;
        select * into a from private.reminder_message_attempts where job_id=p_job_id for update nowait;
        if not found or p_token is null or job.claim_token is null or job.claim_until is null
            or job.claim_token is distinct from p_token or job.claim_until<=p_now
            or a.provider_kind <> 'resend' or a.recovery_state<>'retry-pending' or a.outcome='accepted' or a.provider_id is not null
            or a.post_count>=3 or a.retry_due>p_now then return '{"status":"stale"}'; end if;
        context:=private.email_reminder_context(job.practice_id,job.credential_id,a.provider_namespace,p_now);
        urgency:=case when job.due_date < (p_now at time zone job.timezone)::date then 'past-due'
            when job.due_date = (p_now at time zone job.timezone)::date then 'today' else 'future' end;
        if job.invalidated_at is not null or context is null or context->>'reason' is distinct from 'already-attempted'
            or (context->>'cycleId')::uuid is distinct from job.cycle_id
            or (context->>'dateRevision')::integer is distinct from job.date_revision
            or (context->>'membershipId')::uuid is distinct from job.membership_id
            or (context->>'userId')::uuid is distinct from job.user_id
            or (context->>'selectionVersion')::integer is distinct from job.selection_version
            or (context->>'accountRevision')::bigint is distinct from job.account_revision
            or (context->>'preferenceVersion')::integer is distinct from job.preference_version
            or (context->>'endpointId')::uuid is distinct from job.endpoint_id
            or (context->>'endpointEpoch')::bigint is distinct from job.endpoint_epoch
            or context->>'timezone' is distinct from job.timezone
            or (context->>'dueDate')::date is distinct from job.due_date
            or endpoint.suppressed or endpoint.email is distinct from a.payload->'to'->>0
            or p_config is distinct from jsonb_build_object('namespace',a.provider_namespace,'from',a.payload->>'from',
                'replyTo',a.payload->>'reply_to','appUrl',a.app_origin) or urgency is distinct from a.urgency then
            update private.reminder_message_attempts set recovery_state='canceled',retry_due=null,recovery_version=recovery_version+1 where id=a.id;
            update private.reminder_jobs set invalidated_at=coalesce(invalidated_at,p_now),claim_token=null,claim_until=null where id=job.id;
            return '{"status":"stale"}';
        end if;
        if p_now+interval '30 seconds'>=a.retry_expires then
            update private.reminder_message_attempts set recovery_state='expired',retry_due=null,recovery_version=recovery_version+1 where id=a.id;
            return '{"status":"stale"}';
        end if;
        if private.reminder_next_window(p_now,job.timezone,p_now)>p_now then return '{"status":"window-closed"}'; end if;
        update private.reminder_message_attempts set recovery_state='submitting',post_count=post_count+1,
            retry_due=null,recovery_version=recovery_version+1 where id=a.id returning * into a;
    else return '{"status":"invalid"}'; end if;
    insert into private.reminder_email_submissions(practice_id,attempt_id,ordinal,reserved_at,deadline)
        values(a.practice_id,a.id,a.post_count,p_now,least(p_now+interval '30 seconds',a.retry_expires)) returning * into reservation;
    update private.reminder_jobs set claim_token=null,claim_until=null where id=a.job_id;
    return jsonb_build_object('status','submit','attemptId',a.id,'token',reservation.token,'payload',a.payload,
        'key','reminder-email/'||a.id::text,'submissionId',reservation.id,'ordinal',reservation.ordinal,
        'deadline',reservation.deadline,'expiresAt',a.retry_expires);
exception when lock_not_available then return '{"status":"busy"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.begin_email_reminder_at(p_job_id uuid, p_claim_token uuid, p_config jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if exists(select 1 from private.gmail_reminder_authority where enabled or namespace = p_config->>'namespace') then
        return '{"status":"unavailable"}';
    end if;
    return private.begin_resend_reminder_at(p_job_id, p_claim_token, p_config, p_now);
end;
$function$

CREATE OR REPLACE FUNCTION private.begin_gmail_reminder_at(p_job_id uuid, p_claim_token uuid, p_config jsonb, p_subject text, p_authority_version integer, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare job private.reminder_jobs; authority private.gmail_reminder_authority; permission jsonb; attempt private.reminder_message_attempts;
begin
    select * into job from private.reminder_jobs where id = p_job_id;
    if not found or not private.lock_email_recipient(job.practice_id) then return '{"status":"unavailable"}'; end if;
    select * into authority from private.gmail_reminder_authority where namespace = p_config->>'namespace' for share nowait;
    if not found or not authority.enabled or authority.version is distinct from p_authority_version
        or authority.subject is distinct from p_subject or authority.sender is distinct from p_config->>'from'
        or authority.sender is distinct from p_config->>'replyTo' or authority.app_origin is distinct from p_config->>'appUrl'
        or exists(select 1 from private.reminder_message_attempts where provider_kind = 'resend' and outcome = 'submitting')
        then return '{"status":"unavailable"}'; end if;
    -- The existing begin rechecks every eligibility snapshot under this same practice lock.
    permission := private.begin_resend_reminder_at(p_job_id, p_claim_token, p_config, p_now);
    if permission->>'status' <> 'submit' then return permission; end if;
    update private.reminder_message_attempts set provider_kind = 'gmail', post_count = 1,
        gmail_authority_version = authority.version, gmail_subject = authority.subject,
        app_origin = authority.app_origin where id = (permission->>'attemptId')::uuid returning * into attempt;
    return permission || jsonb_build_object('deadline', attempt.deadline);
exception when lock_not_available then return '{"status":"busy"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.begin_resend_reminder_at(p_job_id uuid, p_claim_token uuid, p_config jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare job private.reminder_jobs; context jsonb; endpoint private.reminder_email_endpoints;
    attempt private.reminder_message_attempts; namespace text := p_config->>'namespace'; payload jsonb; link text; body text; introduction text; urgency text; subject text;
begin
    -- No arbitrary destination/message input. Only constrained server configuration is accepted.
    if jsonb_typeof(p_config) is distinct from 'object' then return '{"status":"invalid"}'::jsonb; end if;
    if exists (select 1 from jsonb_each_text(p_config) where value is null or char_length(value) > 512)
        or (select count(*) from jsonb_object_keys(p_config)) <> 4
        or not (p_config ?& array['namespace','from','replyTo','appUrl'])
        or namespace !~ '^[a-zA-Z0-9_-]{1,80}$'
        or p_config->>'from' !~ '^[a-zA-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-zA-Z0-9.-]+$'
        or p_config->>'replyTo' !~ '^[a-zA-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-zA-Z0-9.-]+$'
        or p_config->>'appUrl' !~ '^https://[a-zA-Z0-9.-]+(:[0-9]+)?$|^http://127[.]0[.]0[.]1:3000$'
        then return '{"status":"invalid"}'::jsonb; end if;
    select * into job from private.reminder_jobs where id = p_job_id;
    if not found or not private.lock_email_recipient(job.practice_id) then return '{"status":"unavailable"}'::jsonb; end if;
    select * into endpoint from private.reminder_email_endpoints where id = job.endpoint_id for update nowait;
    select * into job from private.reminder_jobs where id = p_job_id for update nowait;
    if job.state <> 'claimed' or job.claim_token is distinct from p_claim_token or job.claim_until <= p_now then
        return '{"status":"stale"}'::jsonb;
    end if;
    context := private.email_reminder_context(job.practice_id, job.credential_id, namespace, p_now);
    if context is null or context->>'reason' is not null
        or (context->>'cycleId')::uuid <> job.cycle_id or (context->>'dateRevision')::integer <> job.date_revision
        or (context->>'membershipId')::uuid <> job.membership_id or (context->>'userId')::uuid <> job.user_id
        or (context->>'selectionVersion')::integer <> job.selection_version
        or (context->>'accountRevision')::bigint <> job.account_revision
        or (context->>'preferenceVersion')::integer <> job.preference_version
        or (context->>'endpointId')::uuid is distinct from job.endpoint_id
        or (context->>'endpointEpoch')::bigint is distinct from job.endpoint_epoch
        or endpoint.suppressed or endpoint.provider_namespace <> namespace
        or endpoint.email is distinct from context->>'email'
        or (context->>'target')::timestamptz is distinct from job.nominal_target
        or context->>'scheduleKind' is distinct from job.schedule_kind
        or (context->>'dispatchTarget')::timestamptz is distinct from job.dispatch_target
        or context->>'timezone' <> job.timezone
        or job.next_send_at > p_now then
        update private.reminder_jobs set state = 'canceled', reason = coalesce(context->>'reason', 'eligibility-changed'),
            claim_token = null, claim_until = null, invalidated_at = p_now, updated_at = p_now where id = job.id;
        return '{"status":"stale"}'::jsonb;
    end if;
    if private.reminder_next_window(job.dispatch_target, job.timezone, p_now) > p_now then
        update private.reminder_jobs set state = 'queued', claim_token = null, claim_until = null,
            next_send_at = private.reminder_next_window(job.dispatch_target, job.timezone, p_now), updated_at = p_now where id = job.id;
        return '{"status":"window-closed"}'::jsonb;
    end if;
    attempt.id := gen_random_uuid(); attempt.token := gen_random_uuid();
    link := (p_config->>'appUrl') || '/practice/register/' || job.credential_id::text;
    introduction := case when job.schedule_kind = 'catch-up' then
        'A credential renewal needs attention. Record details or reminder setup became eligible after the ordinary reminder target.'
        else 'A credential renewal needs attention. This reminder was scheduled 60 days before its due date.' end;
    subject := case when job.schedule_kind = 'catch-up' then 'Credential renewal catch-up reminder'
        else 'Credential renewal reminder: 60 days' end;
    urgency := case when job.due_date < (p_now at time zone job.timezone)::date then 'This renewal is past due.'
        when job.due_date = (p_now at time zone job.timezone)::date then 'This renewal is due today.'
        else 'This renewal is due on ' || to_char(job.due_date, 'YYYY-MM-DD') || '.' end;
    body := introduction || ' ' || urgency || ' ' ||
        case when context->>'datePurpose' = 'action-deadline' then 'Action deadline: ' else 'End date: ' end ||
        to_char(job.due_date, 'YYYY-MM-DD') || E'.\nSign in to review the record: ' || link ||
        E'\nThese dates were entered by your practice. Review requirements with the issuer.\nManage reminder emails: ' ||
        (p_config->>'appUrl') || '/practice/reminders';
    payload := jsonb_build_object('from', p_config->>'from', 'to', jsonb_build_array(endpoint.email),
        'reply_to', p_config->>'replyTo', 'subject', subject, 'text', body,
        'html', '<p>' || introduction || '</p><p>' || urgency || '</p><p>' ||
            case when context->>'datePurpose' = 'action-deadline' then 'Action deadline: ' else 'End date: ' end ||
            to_char(job.due_date, 'YYYY-MM-DD') || '.</p><p><a href="' || link || '">Sign in to review the record</a></p>' ||
            '<p>These dates were entered by your practice. Review requirements with the issuer.</p><p><a href="' ||
            (p_config->>'appUrl') || '/practice/reminders">Manage reminder emails</a></p>',
        'tags', jsonb_build_array(jsonb_build_object('name','reminder_attempt','value',attempt.id::text)));
    insert into private.reminder_message_attempts (id, practice_id, job_id, cycle_id, user_id, token,
        endpoint_id, provider_namespace, payload, started_at, deadline, schedule_kind, nominal_target, dispatch_target)
    values (attempt.id, job.practice_id, job.id, job.cycle_id, job.user_id, attempt.token,
        endpoint.id, namespace, payload, p_now, p_now + interval '30 seconds', job.schedule_kind, job.nominal_target, job.dispatch_target) on conflict (cycle_id, user_id, channel) do nothing;
    if not found then return '{"status":"consumed"}'::jsonb; end if;
    update private.reminder_jobs set state = 'submitting', claim_token = null, claim_until = null, updated_at = p_now where id = job.id;
    insert into private.reminder_job_events (practice_id, job_id, operation) values (job.practice_id, job.id, 'begin-submit');
    return jsonb_build_object('status','submit', 'attemptId', attempt.id, 'token', attempt.token,
        'payload', payload, 'key', 'reminder-email/' || attempt.id::text);
exception when lock_not_available then return '{"status":"busy"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.change_reminder_recipient(p_practice_id uuid, p_membership_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    settings private.practice_reminder_settings;
begin
    select * into settings from private.practice_reminder_settings
    where practice_id = p_practice_id for update;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    if settings.membership_id is not distinct from p_membership_id then return; end if;
    update private.practice_reminder_settings set membership_id = p_membership_id,
        version = version + 1, updated_at = pg_catalog.clock_timestamp() where practice_id = p_practice_id;
    insert into private.practice_recipient_events
        (practice_id, actor_user_id, operation, before_membership_id, after_membership_id,
         before_version, after_version, reason)
    values (p_practice_id, auth.uid(),
        case when p_reason is not null then 'member-invalidated'
             when settings.membership_id is null then 'assigned'
             when p_membership_id is null then 'cleared' else 'replaced' end,
        settings.membership_id, p_membership_id, settings.version, settings.version + 1, p_reason);
    if p_membership_id is not null then
        insert into private.reminder_email_preferences (practice_id, user_id)
        select practice_id, user_id from public.practice_memberships where practice_id = p_practice_id and id = p_membership_id
        on conflict do nothing;
    end if;
    perform private.dirty_email_reminders(p_practice_id, 'recipient-changed');
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_email_recovery_at(p_namespace text, p_sending boolean, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare rotation integer; slot integer; i integer; a private.reminder_message_attempts; check_reservation private.reminder_email_checks; lease jsonb; token uuid;
begin
    select s.rotation into rotation from private.reminder_recovery_scan_state s where singleton for update;
    for i in 0..2 loop
        slot:=(rotation+i)%3;
        if slot=0 and p_sending then
            lease:=private.claim_email_reminder_at(p_now);
            if lease is not null then
                update private.reminder_recovery_scan_state set rotation=1 where singleton;
                return lease||'{"kind":"fresh"}'::jsonb;
            end if;
        elsif slot=1 and p_sending then
            for a in select * from private.reminder_message_attempts where provider_kind='resend' and provider_namespace=p_namespace and recovery_state='retry-pending'
                and retry_due<=p_now and (select claim_until is null or claim_until<=p_now from private.reminder_jobs where id=job_id)
                order by retry_due,id limit 100 loop
                perform 1 from private.reminder_jobs where id=a.job_id for update skip locked; if not found then continue; end if;
                select * into a from private.reminder_message_attempts where id=a.id for update skip locked; if not found then continue; end if;
                if a.recovery_state<>'retry-pending' or a.outcome='accepted' then continue; end if;
                token:=gen_random_uuid();
                update private.reminder_jobs set claim_token=token,claim_until=p_now+interval '30 seconds' where id=a.job_id;
                update private.reminder_recovery_scan_state set rotation=2 where singleton;
                return jsonb_build_object('kind','retry','jobId',a.job_id,'token',token);
            end loop;
        elsif slot=2 then
            for a in select * from private.reminder_message_attempts where provider_kind='resend' and provider_namespace=p_namespace and provider_id is not null
                and private.email_check_open(reminder_message_attempts) and check_count<6 and check_due<=p_now and not exists(select 1 from private.reminder_email_checks r where r.attempt_id=reminder_message_attempts.id and r.result is null)
                order by check_due,id limit 100 loop
                perform 1 from private.reminder_jobs where id=a.job_id for update skip locked; if not found then continue; end if;
                select * into a from private.reminder_message_attempts where id=a.id for update skip locked; if not found then continue; end if;
                if not private.email_check_open(a) or a.check_count>=6 or a.check_due is null or a.check_due>p_now or exists(select 1 from private.reminder_email_checks r where r.attempt_id=a.id and r.result is null) then continue; end if;
                update private.reminder_message_attempts set check_count=check_count+1,check_due=null,last_check_reserved=p_now,
                    recovery_version=recovery_version+1 where id=a.id returning * into a;
                insert into private.reminder_email_checks(practice_id,attempt_id,ordinal,reserved_at,deadline)
                    values(a.practice_id,a.id,a.check_count,p_now,p_now+interval '30 seconds') returning * into check_reservation;
                update private.reminder_recovery_scan_state set rotation=0 where singleton;
                return jsonb_build_object('kind','check','attemptId',a.id,'checkId',check_reservation.id,'token',check_reservation.token,'providerId',a.provider_id,
                    'from',a.payload->>'from','to',a.payload->'to'->>0,'deadline',check_reservation.deadline);
            end loop;
        end if;
    end loop;
    return '{"status":"idle"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_email_reminder_at(p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record; job private.reminder_jobs; token uuid := gen_random_uuid();
begin
    for candidate in select id, practice_id, endpoint_id from private.reminder_jobs
        where state in ('queued', 'claimed') and next_send_at <= p_now
            and (state = 'queued' or claim_until <= p_now) order by next_send_at, id limit 100 loop
        if not private.lock_email_recipient(candidate.practice_id) then continue; end if;
        perform 1 from private.reminder_email_endpoints where id = candidate.endpoint_id for update nowait;
        select * into job from private.reminder_jobs where id = candidate.id for update skip locked;
        if not found or job.state not in ('queued', 'claimed') or job.next_send_at > p_now
            or (job.state = 'claimed' and job.claim_until > p_now) then continue; end if;
        if private.reminder_next_window(job.dispatch_target, job.timezone, p_now) is null then
            update private.reminder_jobs set state = 'blocked', reason = 'invalid-target', claim_token = null, claim_until = null where id = job.id;
            continue;
        end if;
        if private.reminder_next_window(job.dispatch_target, job.timezone, p_now) > p_now then
            update private.reminder_jobs set state = 'queued', claim_token = null, claim_until = null,
                next_send_at = private.reminder_next_window(job.dispatch_target, job.timezone, p_now), updated_at = p_now where id = job.id;
            continue;
        end if;
        update private.reminder_jobs set state = 'claimed', claim_token = token, claim_until = p_now + interval '30 seconds', updated_at = p_now
        where id = job.id;
        return jsonb_build_object('jobId', job.id, 'token', token);
    end loop;
    return null;
exception when lock_not_available then return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_renewal_evidence_cleanup(p_evidence_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence private.renewal_evidence; object private.renewal_evidence_objects;
    candidate record; result jsonb := '[]'::jsonb; token uuid;
begin
    for candidate in select e.id, e.practice_id from private.renewal_evidence e
        left join private.renewal_evidence_objects o on o.evidence_id = e.id
        where (p_evidence_id is null or e.id = p_evidence_id)
        and (o.id is not null or e.charged)
        and (o.claim_until is null or o.claim_until <= clock_timestamp())
        and (o.next_check_at is null or o.next_check_at <= clock_timestamp())
        and (e.state in ('deleting', 'deleted', 'abandoned') or (e.state = 'pending' and (
            e.created_at <= clock_timestamp() - interval '24 hours'
            or exists (select 1 from public.credentials c where c.id = e.credential_id and c.archived_at is not null)
            or not exists (select 1 from public.practice_memberships m where m.practice_id = e.practice_id
                and m.user_id = e.actor_user_id and m.state = 'active' and m.role in ('administrator', 'manager')))))
        order by coalesce(o.next_check_at, e.created_at), e.id limit 20
    loop
        perform 1 from public.practices where id = candidate.practice_id for update skip locked;
        if not found then continue; end if;
        select * into evidence from private.renewal_evidence where id = candidate.id;
        select * into object from private.renewal_evidence_objects where evidence_id = evidence.id;
        -- Recheck after lock wait: a successful finalize is never purged.
        if evidence.state = 'available' or object.claim_until > clock_timestamp() then continue; end if;
        if evidence.state = 'pending' and evidence.created_at > clock_timestamp() - interval '24 hours'
            and not exists (select 1 from public.credentials where id = evidence.credential_id and archived_at is not null)
            and exists (select 1 from public.practice_memberships where practice_id = evidence.practice_id
                and user_id = evidence.actor_user_id and state = 'active' and role in ('administrator', 'manager')) then continue; end if;
        if object.id is null and not evidence.charged then continue; end if;
        if evidence.state = 'pending' then
            update private.renewal_evidence set state = 'abandoned', updated_at = clock_timestamp()
            where id = evidence.id returning * into evidence;
            perform private.evidence_event(evidence, null, 'abandoned');
        end if;
        if object.id is null then
            update private.renewal_evidence set state = case when state = 'deleting' then 'deleted' else state end,
                filename = null, charged = false, updated_at = clock_timestamp() where id = evidence.id;
            perform private.evidence_event(evidence, null, 'purge-completed');
            continue;
        end if;
        token := gen_random_uuid();
        update private.renewal_evidence_objects set state = 'purging', claim_token = token,
            claim_until = clock_timestamp() + interval '120 seconds', updated_at = clock_timestamp()
        where id = object.id;
        result := result || jsonb_build_array(jsonb_build_object('objectId', object.id,
            'token', token, 'path', object.object_path));
    end loop;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_renewal_evidence_upload(p_practice_id uuid, p_actor_id uuid, p_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence private.renewal_evidence; object private.renewal_evidence_objects; token uuid; object_id uuid;
begin
    perform private.require_evidence_actor(p_practice_id, p_actor_id, true);
    select * into evidence from private.renewal_evidence where practice_id = p_practice_id and id = p_evidence_id;
    if not found or evidence.actor_user_id <> p_actor_id then return '{"status":"not-found"}'::jsonb; end if;
    if evidence.state <> 'pending' then return jsonb_build_object('status', evidence.state); end if;
    if exists (select 1 from public.credentials where practice_id = p_practice_id
        and id = evidence.credential_id and archived_at is not null) then return '{"status":"archived"}'::jsonb; end if;
    select * into object from private.renewal_evidence_objects where evidence_id = evidence.id;
    if object.claim_until > clock_timestamp() then return '{"status":"busy"}'::jsonb; end if;
    if object.id is null then
        object_id := gen_random_uuid();
        insert into private.renewal_evidence_objects (id, evidence_id, object_path)
        values (object_id, evidence.id, evidence.practice_id::text || '/' || evidence.credential_id::text
            || '/' || evidence.cycle_id::text || '/' || evidence.id::text || '/' || object_id::text || '.' || evidence.file_extension)
        returning * into object;
    end if;
    token := gen_random_uuid();
    update private.renewal_evidence_objects set claim_token = token,
        claim_until = clock_timestamp() + interval '120 seconds', updated_at = clock_timestamp()
    where id = object.id returning * into object;
    return jsonb_build_object('status', 'upload', 'evidenceId', evidence.id, 'objectId', object.id,
        'token', token, 'path', object.object_path, 'mime', evidence.mime, 'byteCount', evidence.byte_count, 'digest', evidence.digest);
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_sms_verification_check(p_practice_id uuid, p_actor_id uuid, p_request_id uuid, p_challenge_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; enrollment private.practice_sms_enrollments; challenge private.sms_verification_challenges; endpoint private.sms_phone_endpoints; request private.sms_verification_requests; now_at timestamptz:=pg_catalog.clock_timestamp(); payload jsonb; token uuid;
begin
    member := private.sms_member(p_practice_id,p_actor_id,true);
    if p_request_id is null or p_expected_version is null or p_expected_version<1 then raise exception 'Invalid check input' using errcode='23514'; end if;
    select * into challenge from private.sms_verification_challenges where id=p_challenge_id and practice_id=p_practice_id and membership_id=member;
    if not found then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    select * into endpoint from private.sms_phone_endpoints where id=challenge.endpoint_id for update;
    select * into enrollment from private.practice_sms_enrollments where practice_id=p_practice_id and membership_id=member for update;
    select * into challenge from private.sms_verification_challenges where id=p_challenge_id for update;
    payload := pg_catalog.jsonb_build_object('challenge',p_challenge_id,'version',p_expected_version);
    if exists (select 1 from private.sms_action_receipts where practice_id=p_practice_id and actor_user_id=p_actor_id and request_id=p_request_id) then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    select * into request from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=p_actor_id and request_id=p_request_id for update;
    now_at := pg_catalog.clock_timestamp();
    if found then
        if request.intent<>'check' or request.payload<>payload then return private.sms_reply(p_practice_id,member,'conflict'); end if;
        if request.state='claimed' and request.lease_until<=now_at then
            update private.sms_verification_requests set state='uncertain',outcome='uncertain' where id=request.id;
            update private.sms_verification_challenges set state='uncertain' where id=challenge.id and state='pending';
        end if;
        return private.sms_reply(p_practice_id,member,case when request.state='complete' then coalesce(request.outcome,'success') else 'uncertain' end);
    end if;
    if enrollment.version<>p_expected_version then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if endpoint.provider_blocked or enrollment.phone_revision<>challenge.phone_revision or enrollment.endpoint_id<>endpoint.id or challenge.state<>'pending'
        or challenge.verification_sid is null or challenge.expires_at<=now_at or challenge.check_count>=5 then return private.sms_reply(p_practice_id,member,'verification-required'); end if;
    if exists (select 1 from private.sms_verification_requests where challenge_id=challenge.id and state in ('claimed','uncertain')) then return private.sms_reply(p_practice_id,member,'busy'); end if;
    token := gen_random_uuid();
    update private.sms_verification_challenges set check_count=check_count+1 where id=challenge.id;
    insert into private.sms_verification_requests (actor_user_id,practice_id,membership_id,request_id,challenge_id,intent,payload,state,claim_token,reserved_at,lease_until)
        values (p_actor_id,p_practice_id,member,p_request_id,challenge.id,'check',payload,'claimed',token,now_at,now_at+interval '30 seconds');
    return pg_catalog.jsonb_build_object('status','claimed','claimToken',token,'phone',endpoint.phone_e164,'accountSid',endpoint.account_sid,'messagingServiceSid',endpoint.messaging_service_sid,'verifyServiceSid',challenge.verify_service_sid,'verificationSid',challenge.verification_sid,'challengeId',challenge.id);
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_sms_verification_send(p_practice_id uuid, p_actor_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; request private.sms_verification_requests; challenge private.sms_verification_challenges; endpoint private.sms_phone_endpoints; enrollment private.practice_sms_enrollments; now_at timestamptz := pg_catalog.clock_timestamp(); token uuid;
begin
    member := private.sms_member(p_practice_id,p_actor_id,true);
    select * into request from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=p_actor_id and request_id=p_request_id and intent='send';
    if not found or request.membership_id<>member then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    select e.* into endpoint from private.sms_phone_endpoints e join private.sms_verification_challenges c on c.endpoint_id=e.id where c.id=request.challenge_id for update of e;
    select * into enrollment from private.practice_sms_enrollments where practice_id=p_practice_id and membership_id=member for update;
    select * into challenge from private.sms_verification_challenges where id=request.challenge_id for update;
    select * into request from private.sms_verification_requests where id=request.id for update;
    now_at := pg_catalog.clock_timestamp();
    if request.state<>'prepared' then
        if request.state='claimed' and request.lease_until<=now_at then
            update private.sms_verification_requests set state='uncertain',outcome='uncertain' where id=request.id;
            update private.sms_verification_challenges set state='uncertain' where id=challenge.id and state in ('reserved','pending');
        end if;
        return private.sms_reply(p_practice_id,member,case when request.state='complete' then 'success' else 'uncertain' end);
    end if;
    if endpoint.provider_blocked or enrollment.phone_revision<>challenge.phone_revision or enrollment.endpoint_id<>endpoint.id
        or challenge.state not in ('reserved','pending') or challenge.expires_at<=now_at then return private.sms_reply(p_practice_id,member,'verification-required'); end if;
    if exists (select 1 from private.sms_verification_requests where challenge_id=challenge.id and state in ('claimed','uncertain')) then return private.sms_reply(p_practice_id,member,'busy'); end if;
    if exists (select 1 from private.sms_verification_requests r join private.sms_verification_challenges c on c.id=r.challenge_id
        where r.intent='send' and r.reserved_at>now_at-interval '60 seconds' and (r.actor_user_id=p_actor_id or c.endpoint_id=endpoint.id))
        or (select count(*) from private.sms_verification_requests where intent='send' and actor_user_id=p_actor_id and reserved_at>now_at-interval '30 minutes')>=5
        or (select count(*) from private.sms_verification_requests where intent='send' and actor_user_id=p_actor_id and reserved_at>now_at-interval '24 hours')>=10
        or (select count(*) from private.sms_verification_requests r join private.sms_verification_challenges c on c.id=r.challenge_id where r.intent='send' and c.endpoint_id=endpoint.id and r.reserved_at>now_at-interval '30 minutes')>=5
        or (select count(*) from private.sms_verification_requests r join private.sms_verification_challenges c on c.id=r.challenge_id where r.intent='send' and c.endpoint_id=endpoint.id and r.reserved_at>now_at-interval '24 hours')>=10
        or (select count(*) from private.sms_verification_requests where intent='send' and practice_id=p_practice_id and reserved_at>now_at-interval '24 hours')>=100 then return private.sms_reply(p_practice_id,member,'rate-limited'); end if;
    token := gen_random_uuid();
    update private.sms_verification_requests set state='claimed',claim_token=token,reserved_at=now_at,lease_until=now_at+interval '30 seconds' where id=request.id;
    return pg_catalog.jsonb_build_object('status','claimed','claimToken',token,'phone',endpoint.phone_e164,'accountSid',endpoint.account_sid,'messagingServiceSid',endpoint.messaging_service_sid,'verifyServiceSid',challenge.verify_service_sid,'verificationSid',challenge.verification_sid,'challengeId',challenge.id);
end;
$function$

CREATE OR REPLACE FUNCTION private.complete_credential_renewal(p_practice_id uuid, p_request_id uuid, p_credential_id uuid, p_expected_version integer, p_expected_cycle_id uuid, p_expected_date_revision integer, p_expected_renewal_version integer, p_end_date text, p_action_deadline text, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare credential public.credentials; cycle public.credential_cycles; successor public.credential_cycles;
    receipt private.renewal_completion_requests; entered_end date; entered_action date;
    payload jsonb; current_data jsonb; before_data jsonb; after_data jsonb; result jsonb;
    occurred timestamptz; today date; zone text; completed_data jsonb;
begin
    perform private.require_register_member(p_practice_id, true);
    if p_confirmed is distinct from true or p_request_id is null or p_credential_id is null
        or p_expected_cycle_id is null or p_expected_version is null or p_expected_version < 1
        or p_expected_date_revision is null or p_expected_date_revision < 1
        or p_expected_renewal_version is null or p_expected_renewal_version < 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    begin entered_end := private.credential_date(p_end_date);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"endDate":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    begin entered_action := private.credential_date(p_action_deadline);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"actionDeadline":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    payload := pg_catalog.jsonb_build_object('credentialId', p_credential_id, 'expectedVersion', p_expected_version,
        'expectedCycleId', p_expected_cycle_id, 'expectedDateRevision', p_expected_date_revision,
        'expectedRenewalVersion', p_expected_renewal_version, 'endDate', entered_end,
        'actionDeadline', entered_action, 'confirmed', p_confirmed);
    select * into receipt from private.renewal_completion_requests
    where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id;
    if found then
        if receipt.payload <> payload then return '{"status":"request-conflict"}'::jsonb; end if;
        return receipt.result;
    end if;
    select * into credential from public.credentials where practice_id = p_practice_id and id = p_credential_id;
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    cycle := private.current_credential_cycle(p_practice_id, credential.id);
    if credential.archived_at is not null then return '{"status":"archived"}'::jsonb; end if;
    if cycle.completed_at is not null then return '{"status":"completed"}'::jsonb; end if;
    current_data := private.credential_maintenance_projection(credential)
        || pg_catalog.jsonb_build_object('renewal', private.renewal_projection(credential));
    if credential.version <> p_expected_version or cycle.id <> p_expected_cycle_id
        or cycle.date_revision <> p_expected_date_revision
        or (current_data->'renewal'->'workflow'->>'version')::integer <> p_expected_renewal_version
        or credential.version = 2147483647 or cycle.cycle_number = 2147483647 then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', current_data);
    end if;
    occurred := private.renewal_completion_clock();
    select timezone into zone from public.practices where id = p_practice_id;
    today := (occurred at time zone zone)::date;
    if entered_end is null or entered_end <= today then
        return '{"status":"invalid","errors":{"endDate":"Enter an end date after today in the practice timezone."}}'::jsonb;
    end if;
    if entered_action is not null and entered_action <= today then
        return '{"status":"invalid","errors":{"actionDeadline":"Enter an action deadline after today in the practice timezone."}}'::jsonb;
    end if;
    if entered_action is not null and entered_action >= entered_end then
        return '{"status":"invalid","errors":{"actionDeadline":"The action deadline must be earlier than the end date."}}'::jsonb;
    end if;
    before_data := current_data;
    update public.credential_cycles set completed_at = occurred, updated_at = occurred
    where practice_id = p_practice_id and id = cycle.id returning * into cycle;
    insert into public.credential_cycles (practice_id, credential_id, cycle_number, date_revision,
        end_date, action_deadline, created_at, updated_at)
    values (p_practice_id, credential.id, cycle.cycle_number + 1, 1, entered_end, entered_action, occurred, occurred)
    returning * into successor;
    update public.credentials set version = version + 1, updated_at = occurred
    where practice_id = p_practice_id and id = credential.id returning * into credential;
    after_data := private.credential_maintenance_projection(credential)
        || pg_catalog.jsonb_build_object('renewal', private.renewal_projection(credential));
    insert into private.credential_renewal_completions
        (practice_id, credential_id, predecessor_id, successor_id, actor_user_id, completed_at, before_data, after_data)
    values (p_practice_id, credential.id, cycle.id, successor.id, auth.uid(), occurred, before_data, after_data);
    completed_data := private.renewal_cycle_history(cycle, credential.type);
    insert into private.renewal_audit_events (practice_id, actor_user_id, credential_id, cycle_id,
        operation, before_data, after_data, occurred_at)
    values (p_practice_id, auth.uid(), credential.id, cycle.id, 'renewal-confirmed', before_data,
        pg_catalog.jsonb_build_object('completedCycle', completed_data, 'credential', after_data), occurred);
    result := pg_catalog.jsonb_build_object('status', 'success', 'changed', true,
        'completedCycle', completed_data, 'credential', after_data);
    insert into private.renewal_completion_requests (practice_id, actor_user_id, request_id,
        credential_id, predecessor_id, successor_id, payload, result, created_at)
    values (p_practice_id, auth.uid(), p_request_id, credential.id, cycle.id, successor.id, payload, result, occurred);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.consent_my_practice_sms(p_practice_id uuid, p_request_id uuid, p_expected_version integer, p_consent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; enrollment private.practice_sms_enrollments; endpoint private.sms_phone_endpoints; receipt private.sms_action_receipts; event uuid; payload jsonb;
begin
    member := private.sms_member(p_practice_id,auth.uid(),true);
    if p_consent is distinct from true or p_request_id is null or p_expected_version is null or p_expected_version < 1 then
        raise exception 'Explicit consent required' using errcode = '23514';
    end if;
    select e.* into endpoint from private.sms_phone_endpoints e join private.practice_sms_enrollments s on s.endpoint_id = e.id
        where s.practice_id = p_practice_id and s.membership_id = member for update of e;
    select * into enrollment from private.practice_sms_enrollments where practice_id = p_practice_id and membership_id = member for update;
    payload := pg_catalog.jsonb_build_object('version',p_expected_version,'consent',true,'disclosure','e4-s1-v1');
    select * into receipt from private.sms_action_receipts where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id;
    if found then
        return private.sms_reply(p_practice_id,member,case when receipt.intent = 'consent' and receipt.payload = payload then 'success' else 'conflict' end);
    end if;
    if exists (select 1 from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=auth.uid() and request_id=p_request_id) then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if enrollment.version is distinct from p_expected_version then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if endpoint.id is null or endpoint.provider_blocked or enrollment.verified_revision is distinct from enrollment.phone_revision then
        return private.sms_reply(p_practice_id,member,'verification-required');
    end if;
    if enrollment.consent_event_id is null then
        insert into private.sms_enrollment_events (practice_id,membership_id,actor_user_id,phone_revision,endpoint_id,kind,disclosure_version,disclosure_text)
        values (p_practice_id,member,auth.uid(),enrollment.phone_revision,endpoint.id,'reminder-consent','e4-s1-v1',private.sms_disclosure('reminder-consent',p_practice_id)) returning id into event;
        update private.practice_sms_enrollments set consent_event_id=event,consent_epoch=endpoint.suppression_epoch,withdrawn=false,version=version+1
        where practice_id=p_practice_id and membership_id=member;
    end if;
    perform private.sms_receipt(p_practice_id,member,auth.uid(),p_request_id,'consent',payload);
    return private.sms_reply(p_practice_id,member,'success');
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice(p_name text, p_timezone text)
 RETURNS practices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result public.practices;
    actor uuid := auth.uid();
begin
    if actor is null or not exists (select 1 from auth.users
                                   where id = actor and email_confirmed_at is not null) then
        raise exception 'forbidden' using errcode = '42501';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text, 0));
    select p.* into result from public.practices as p
    join public.practice_memberships as m on m.practice_id = p.id
    where m.user_id = actor and m.state = 'active';
    if found then return result; end if;
    insert into public.practices (name, timezone) values (p_name, p_timezone)
    returning * into result;
    insert into public.practice_memberships (practice_id, user_id, role)
    values (result.id, actor, 'administrator');
    insert into private.practice_reminder_settings (practice_id) values (result.id);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_clinician(p_practice_id uuid, p_request_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    payload jsonb;
    result jsonb;
    clinician public.clinicians;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_name);
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    payload := pg_catalog.jsonb_build_object('name', normalized);
    result := private.register_replay(p_practice_id, p_request_id, 'clinician-created', payload);
    if result is not null then return result; end if;
    insert into public.clinicians (practice_id, name) values (p_practice_id, normalized)
    returning * into clinician;
    result := pg_catalog.jsonb_build_object('status', 'success', 'clinician',
        pg_catalog.jsonb_build_object('id', clinician.id, 'name', clinician.name,
            'version', clinician.version));
    return private.finish_register_create(p_practice_id, p_request_id, 'clinician-created', payload,
        clinician.id, null, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
    result jsonb;
    credential public.credentials;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_title);
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy', 'pci_compliance_certificate')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_type = 'pci_compliance_certificate' and p_owner_kind <> 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered);
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', payload);
    if result is not null then return result; end if;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (
        select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )
    ) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id)
    values (p_practice_id, normalized, p_type, p_owner_kind, p_owner_clinician_id)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created', payload,
        null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential_with_details(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[], p_issuer text, p_jurisdiction text, p_end_date text, p_action_deadline text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    issuer text;
    jurisdiction text;
    entered_end_date date;
    entered_action_deadline date;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
    result jsonb;
    credential public.credentials;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_title);
    issuer := nullif(private.register_name(p_issuer), '');
    jurisdiction := nullif(private.register_name(p_jurisdiction), '');
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy', 'pci_compliance_certificate')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_type = 'pci_compliance_certificate' and p_owner_kind <> 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if issuer is not null and char_length(issuer) > 120 then
        return '{"status":"invalid","errors":{"issuer":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    if jurisdiction is not null and char_length(jurisdiction) > 120 then
        return '{"status":"invalid","errors":{"jurisdiction":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    begin
        entered_end_date := private.credential_date(p_end_date);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"endDate":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    begin
        entered_action_deadline := private.credential_date(p_action_deadline);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"actionDeadline":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    if entered_end_date is not null and entered_action_deadline is not null and entered_action_deadline >= entered_end_date then
        return '{"status":"invalid","errors":{"actionDeadline":"The action deadline must be earlier than the end date."}}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered, 'contract_version', 2, 'issuer', issuer,
        'jurisdiction', jurisdiction, 'end_date', pg_catalog.to_char(entered_end_date, 'YYYY-MM-DD'),
        'action_deadline', pg_catalog.to_char(entered_action_deadline, 'YYYY-MM-DD'));
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', payload);
    if result is not null then return result; end if;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (
        select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )
    ) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id, issuer, jurisdiction)
    values (p_practice_id, normalized, p_type, p_owner_kind, p_owner_clinician_id, issuer, jurisdiction)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    update public.credential_cycles cy set end_date = entered_end_date,
        action_deadline = entered_action_deadline,
        updated_at = pg_catalog.clock_timestamp()
    where cy.practice_id = p_practice_id and cy.credential_id = credential.id and cy.cycle_number = 1;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_details_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created', payload,
        null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential_with_number(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[], p_issuer text, p_jurisdiction text, p_end_date text, p_action_deadline text, p_record_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare values_json jsonb; normalized_number text; result jsonb;
    credential public.credentials; covered uuid[];
begin
    perform private.require_register_member(p_practice_id, true);
    if p_request_id is null then return '{"status":"invalid"}'::jsonb; end if;
    values_json := private.credential_change_values(p_title, p_type, p_owner_kind,
        p_owner_clinician_id, p_covered_clinician_ids, p_issuer, p_jurisdiction,
        p_end_date, p_action_deadline);
    if values_json ? 'status' then return values_json; end if;
    begin normalized_number := private.credential_record_number(p_record_number);
    exception when invalid_parameter_value then
        return '{"status":"invalid","errors":{"recordNumber":"Use up to 120 characters without control characters."}}'::jsonb;
    end;
    values_json := values_json || pg_catalog.jsonb_build_object(
        'contract_version', 3, 'record_number', normalized_number);
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', values_json);
    if result is not null then return result; end if;
    select coalesce(array_agg(x::uuid order by x::uuid), '{}'::uuid[]) into covered
    from pg_catalog.jsonb_array_elements_text(values_json->'covered_clinician_ids') x;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (select 1 from unnest(covered) x where not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = x
    )) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id,
        issuer, jurisdiction, record_number)
    values (p_practice_id, values_json->>'title', p_type, p_owner_kind, p_owner_clinician_id,
        values_json->>'issuer', values_json->>'jurisdiction', normalized_number)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    update public.credential_cycles set end_date = (values_json->>'end_date')::date,
        action_deadline = (values_json->>'action_deadline')::date,
        updated_at = pg_catalog.clock_timestamp()
    where practice_id = p_practice_id and credential_id = credential.id and cycle_number = 1;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_details_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created',
        values_json, null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_invitation(p_practice_id uuid, p_email text, p_role text, p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    canonical text;
    issued timestamptz;
    result private.practice_invitations;
begin
    perform private.require_administrator(p_practice_id);
    canonical := private.canonical_invitation_email(p_email);
    if p_role is null or p_role not in ('administrator','manager','viewer')
       or p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$' then
        raise exception 'Invalid invitation' using errcode='23514';
    end if;
    if exists(select 1 from private.practice_invitations
              where practice_id=p_practice_id and email=canonical and state='pending') then
        return '{"status":"invite-exists"}'::jsonb;
    end if;
    issued := pg_catalog.clock_timestamp();
    insert into private.practice_invitations
        (practice_id,email,role,token_digest,creator_user_id,issued_at,expires_at)
    values(p_practice_id,canonical,p_role,p_token_digest,auth.uid(),issued,issued+interval '168 hours')
    returning * into result;
    return pg_catalog.jsonb_build_object('status','success','invitation',private.invitation_projection(result));
end;
$function$

CREATE OR REPLACE FUNCTION private.credential_change_values(p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[], p_issuer text, p_jurisdiction text, p_end_date text, p_action_deadline text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
    normalized text;
    issuer text;
    jurisdiction text;
    entered_end_date date;
    entered_action_deadline date;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
begin
    normalized := private.register_name(p_title);
    issuer := nullif(private.register_name(p_issuer), '');
    jurisdiction := nullif(private.register_name(p_jurisdiction), '');
    if normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy', 'pci_compliance_certificate')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_type = 'pci_compliance_certificate' and p_owner_kind <> 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if issuer is not null and char_length(issuer) > 120 then
        return '{"status":"invalid","errors":{"issuer":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    if jurisdiction is not null and char_length(jurisdiction) > 120 then
        return '{"status":"invalid","errors":{"jurisdiction":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    begin
        entered_end_date := private.credential_date(p_end_date);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"endDate":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    begin
        entered_action_deadline := private.credential_date(p_action_deadline);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"actionDeadline":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    if entered_end_date is not null and entered_action_deadline is not null and entered_action_deadline >= entered_end_date then
        return '{"status":"invalid","errors":{"actionDeadline":"The action deadline must be earlier than the end date."}}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered, 'contract_version', 2, 'issuer', issuer,
        'jurisdiction', jurisdiction, 'end_date', pg_catalog.to_char(entered_end_date, 'YYYY-MM-DD'),
        'action_deadline', pg_catalog.to_char(entered_action_deadline, 'YYYY-MM-DD'));
    return payload;
end;
$function$

CREATE OR REPLACE FUNCTION private.credential_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
    if p_value is null or p_value = '' then return null; end if;
    if char_length(p_value) <> 10 or p_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or substring(p_value from 1 for 4)::integer = 0 then
        raise exception 'invalid credential date' using errcode = '22008';
    end if;
    return pg_catalog.make_date(substring(p_value from 1 for 4)::integer,
        substring(p_value from 6 for 2)::integer, substring(p_value from 9 for 2)::integer);
end;
$function$

CREATE OR REPLACE FUNCTION private.credential_record_number(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare normalized text := nullif(private.register_name(p_value), '');
begin
    if normalized is not null and (char_length(normalized) > 120
        or normalized ~ U&'[\0001-\001F\007F-\009F]') then
        raise exception 'invalid record number' using errcode = '22023';
    end if;
    return normalized;
end;
$function$

CREATE OR REPLACE FUNCTION private.current_credential_cycle(p_practice_id uuid, p_credential_id uuid)
 RETURNS credential_cycles
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare result public.credential_cycles;
begin
    select * into result from public.credential_cycles
    where practice_id = p_practice_id and credential_id = p_credential_id
    order by cycle_number desc limit 1;
    if not found then raise exception 'missing credential cycle'; end if;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.drain_email_account_changes()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record; account private.reminder_email_account_state; practice_id uuid; processed integer := 0;
    scan private.reminder_account_scan_state; last_id uuid;
begin
    select * into scan from private.reminder_account_scan_state;
    for candidate in select user_id, revision from private.reminder_email_account_state
        where dirty and (scan.cursor_id is null or user_id > scan.cursor_id) order by user_id limit 100 loop
        last_id := candidate.user_id;
        select m.practice_id into practice_id from public.practice_memberships m where m.user_id = candidate.user_id and m.state = 'active';
        begin
            if practice_id is not null then
                perform 1 from public.practices where id = practice_id for update nowait;
            end if;
            perform 1 from auth.users where id = candidate.user_id for share nowait;
            select * into account from private.reminder_email_account_state where user_id = candidate.user_id for update nowait;
            if account.revision <> candidate.revision then continue; end if;
            if practice_id is not null then
                perform private.dirty_email_reminders(practice_id, 'email-account-changed');
            end if;
            update private.reminder_email_account_state set dirty = false where user_id = candidate.user_id and revision = candidate.revision;
            processed := processed + 1;
        exception when lock_not_available then continue;
        end;
    end loop;
    if last_id is null or not exists (select 1 from private.reminder_email_account_state where dirty and user_id > last_id) then
        last_id := null;
    end if;
    -- Cursor is acquired last and acknowledged by observed version, never before practice/Auth.
    update private.reminder_account_scan_state set cursor_id = last_id, version = version + 1 where version = scan.version;
    return processed;
end;
$function$

CREATE OR REPLACE FUNCTION private.email_recovery_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if new.provider_kind = 'resend' and new.outcome = 'accepted' and new.recovery_state <> 'legacy' then
        new.recovery_state := 'accepted'; new.retry_due := null;
        if old.outcome <> 'accepted' then
            new.recovery_version := new.recovery_version + 1;
            if new.check_count = 0 and new.check_due is null then new.check_due := clock_timestamp() + interval '5 minutes'; end if;
        end if;
    end if;
    if not private.email_check_open(new) then new.check_due := null; end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.email_reminder_binding(p_namespace text, p_provider_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
AS $function$
declare attempt private.reminder_message_attempts;
begin
    select * into attempt from private.reminder_message_attempts
    where provider_kind = 'resend' and provider_namespace = p_namespace and (provider_id = p_provider_id or (id = p_attempt_id and provider_id is null)) limit 1;
    if not found then return '{"status":"missing"}'::jsonb; end if;
    return jsonb_build_object('attemptId', attempt.id, 'providerId', attempt.provider_id,
        'from', attempt.payload->>'from', 'to', attempt.payload->'to');
end;
$function$

CREATE OR REPLACE FUNCTION private.email_reminder_context(p_practice_id uuid, p_credential_id uuid, p_namespace text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare result jsonb; authority private.gmail_reminder_authority;
begin
    result := private.resend_reminder_context(p_practice_id, p_credential_id, p_namespace, p_now);
    select * into authority from private.gmail_reminder_authority where namespace = p_namespace;
    if found and result->>'reason' is null then
        if not authority.enabled then result := jsonb_set(result, '{reason}', '"gmail-unavailable"');
        elsif result->>'email' is distinct from authority.allowed_recipient then
            result := jsonb_set(result, '{reason}', '"gmail-recipient-blocked"');
        end if;
    end if;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_administrator()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    target uuid;
begin
    if tg_table_name = 'practices' then
        target := new.id;
    elsif tg_op = 'DELETE' then
        target := old.practice_id;
    else
        target := new.practice_id;
    end if;
    perform 1 from public.practices where id = target for update;
    if found and not exists (select 1 from public.practice_memberships
                             where practice_id = target and state = 'active'
                               and role = 'administrator') then
        raise exception 'Practice requires an active administrator' using errcode = '23514';
    end if;
    if tg_table_name = 'practice_memberships' then
        if tg_op = 'UPDATE' then
            if old.practice_id <> new.practice_id then
                raise exception 'Membership practice is immutable' using errcode = '23514';
            end if;
        end if;
    end if;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.expire_email_recovery_at(p_now timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item record; changed integer:=0; attempt private.reminder_message_attempts;
begin
    for item in select s.id,s.attempt_id,a.job_id from private.reminder_email_submissions s
        join private.reminder_message_attempts a on a.id=s.attempt_id where s.result is null and s.deadline<=p_now order by s.deadline,s.id limit 100 loop
        perform 1 from private.reminder_jobs where id=item.job_id for update skip locked; if not found then continue; end if;
        perform 1 from private.reminder_message_attempts where id=item.attempt_id for update skip locked; if not found then continue; end if;
        perform 1 from private.reminder_email_submissions where id=item.id for update skip locked; if not found then continue; end if;
        update private.reminder_email_submissions set result='{"kind":"uncertain","reason":"expired"}',observed_at=p_now where id=item.id and result is null;
        if found then
            update private.reminder_message_attempts set recovery_state='uncertain',retry_due=null,outcome='uncertain',recovery_version=recovery_version+1
                where id=item.attempt_id and outcome<>'accepted'; changed:=changed+1;
        end if;
    end loop;
    for item in select r.id,r.attempt_id,a.job_id from private.reminder_email_checks r join private.reminder_message_attempts a on a.id=r.attempt_id
        where r.result is null and r.deadline<=p_now order by r.deadline,r.id limit 100 loop
        perform 1 from private.reminder_jobs where id=item.job_id for update skip locked; if not found then continue; end if;
        select * into attempt from private.reminder_message_attempts where id=item.attempt_id for update skip locked; if not found then continue; end if;
        update private.reminder_email_checks set result='{"matched":false,"status":null,"bounced":false}',observed_at=p_now where id=item.id and result is null;
        if found then
            update private.reminder_message_attempts set check_due=case when check_count<6 and private.email_check_open(reminder_message_attempts) then p_now+private.email_check_delay(check_count) end,
                recovery_version=recovery_version+1 where id=attempt.id; changed:=changed+1;
        end if;
    end loop;
    for item in select id,job_id from private.reminder_message_attempts
        where recovery_state='retry-pending' and retry_expires<=p_now order by retry_expires,id limit 100 loop
        perform 1 from private.reminder_jobs where id=item.job_id for update skip locked; if not found then continue; end if;
        perform 1 from private.reminder_message_attempts where id=item.id for update skip locked; if not found then continue; end if;
        update private.reminder_message_attempts set recovery_state='expired',retry_due=null,recovery_version=recovery_version+1
            where id=item.id and recovery_state='retry-pending' and retry_expires<=p_now;
        if found then changed:=changed+1; end if;
    end loop;
    return changed;
end;
$function$

CREATE OR REPLACE FUNCTION private.expire_email_submissions_at(p_now timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record; changed integer := 0;
begin
    for candidate in select id, job_id from private.reminder_message_attempts
        where provider_kind = 'resend' and outcome = 'submitting' and deadline <= p_now order by deadline, id limit 100 loop
        perform 1 from private.reminder_jobs where id = candidate.job_id for update skip locked;
        if not found then continue; end if;
        perform 1 from private.reminder_message_attempts where id = candidate.id for update skip locked;
        if not found then continue; end if;
        update private.reminder_message_attempts set outcome = 'uncertain', error_category = 'interrupted'
        where id = candidate.id and outcome = 'submitting' and deadline <= p_now;
        if found then
            update private.reminder_jobs set state = 'uncertain', updated_at = p_now where id = candidate.job_id and state = 'submitting';
            changed := changed + 1;
        end if;
    end loop;
    return changed;
end;
$function$

CREATE OR REPLACE FUNCTION private.expire_gmail_reminders_at(p_now timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item record; changed integer := 0;
begin
    for item in select id, job_id, practice_id from private.reminder_message_attempts
        where provider_kind = 'gmail' and outcome = 'submitting' and deadline <= p_now order by deadline, id limit 100 loop
        perform 1 from private.reminder_jobs where id = item.job_id for update skip locked;
        if not found then continue; end if;
        update private.reminder_message_attempts set outcome = 'uncertain', error_category = 'interrupted'
            where id = item.id and outcome = 'submitting' and deadline <= p_now;
        if found then
            update private.reminder_jobs set state = 'uncertain', updated_at = p_now where id = item.job_id;
            insert into private.reminder_job_events(practice_id, job_id, operation, occurred_at)
                values(item.practice_id, item.job_id, 'gmail-permission-expired', p_now);
            changed := changed + 1;
        end if;
    end loop;
    return changed;
end;
$function$

CREATE OR REPLACE FUNCTION private.finalize_renewal_evidence_upload(p_practice_id uuid, p_actor_id uuid, p_evidence_id uuid, p_token uuid, p_byte_count integer, p_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence private.renewal_evidence; object private.renewal_evidence_objects;
begin
    perform private.require_evidence_actor(p_practice_id, p_actor_id, true);
    select * into evidence from private.renewal_evidence where practice_id = p_practice_id and id = p_evidence_id;
    if not found or evidence.actor_user_id <> p_actor_id then return '{"status":"not-found"}'::jsonb; end if;
    if p_byte_count is distinct from evidence.byte_count or p_digest is distinct from evidence.digest then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if evidence.state = 'available' then return jsonb_build_object('status', 'success', 'evidenceId', evidence.id, 'state', 'available'); end if;
    if evidence.state <> 'pending' then return jsonb_build_object('status', evidence.state); end if;
    if exists (select 1 from public.credentials where practice_id = p_practice_id
        and id = evidence.credential_id and archived_at is not null) then return '{"status":"archived"}'::jsonb; end if;
    select * into object from private.renewal_evidence_objects where evidence_id = evidence.id;
    if p_token is null or object.claim_token is distinct from p_token or object.claim_until <= clock_timestamp()
        or object.claim_until is null or object.state <> 'pending' then return '{"status":"busy"}'::jsonb; end if;
    update private.renewal_evidence_objects set state = 'verified', claim_token = null,
        claim_until = null, updated_at = clock_timestamp() where id = object.id;
    update private.renewal_evidence set state = 'available', version = 2, updated_at = clock_timestamp()
    where id = evidence.id returning * into evidence;
    perform private.evidence_event(evidence, p_actor_id, 'uploaded');
    return jsonb_build_object('status', 'success', 'evidenceId', evidence.id, 'state', evidence.state);
end;
$function$

CREATE OR REPLACE FUNCTION private.finish_register_create(p_practice_id uuid, p_request_id uuid, p_operation text, p_payload jsonb, p_clinician_id uuid, p_credential_id uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    insert into private.register_audit_events
        (practice_id, actor_user_id, operation, clinician_id, credential_id, after_data)
    values (p_practice_id, auth.uid(), p_operation, p_clinician_id, p_credential_id,
        case when p_operation = 'clinician-created' then p_result->'clinician'
             else p_result->'credential' end);
    insert into private.register_create_requests
        (practice_id, actor_user_id, request_id, operation, payload, result)
    values (p_practice_id, auth.uid(), p_request_id, p_operation, p_payload, p_result);
    if p_credential_id is not null then
        perform private.dirty_email_reminders(p_practice_id, 'credential-created', p_credential_id);
    end if;
    return p_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.get_credential_renewal_history(p_practice_id uuid, p_credential_id uuid, p_before_cycle_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare credential public.credentials; cycle public.credential_cycles; items jsonb; next_cursor integer;
begin
    perform private.require_register_member(p_practice_id, false);
    if p_credential_id is null or (p_before_cycle_number is not null and p_before_cycle_number < 1) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    select * into credential from public.credentials where practice_id = p_practice_id and id = p_credential_id;
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    cycle := private.current_credential_cycle(p_practice_id, credential.id);
    with page as (
        select cy.*, row_number() over (order by cycle_number desc) position
        from public.credential_cycles cy where practice_id = p_practice_id and credential_id = credential.id
            and (p_before_cycle_number is null or cycle_number < p_before_cycle_number)
        order by cycle_number desc limit 21
    ) select coalesce(jsonb_agg(private.renewal_cycle_history(cy, credential.type) order by cy.cycle_number desc)
            filter (where page.position <= 20), '[]'::jsonb),
        case when count(*) > 20 then min(page.cycle_number) filter (where page.position <= 20) end
    into items, next_cursor from page
    join public.credential_cycles cy on cy.id = page.id and cy.practice_id = p_practice_id;
    return pg_catalog.jsonb_build_object('status', 'success', 'credentialId', credential.id,
        'title', credential.title, 'archivedAt', credential.archived_at, 'currentCycleId', cycle.id,
        'cycles', items, 'nextBeforeCycleNumber', next_cursor);
end;
$function$

CREATE OR REPLACE FUNCTION private.get_email_reminder_history_v2(p_practice_id uuid, p_credential_id uuid, p_after uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
AS $function$
declare result jsonb; rows jsonb;
begin
