        else 'ready' end;
    with page as (
        select c.id, c.title, cy.id cycle_id, coalesce(cy.action_deadline,cy.end_date) due,
            case when cy.action_deadline is not null then 'action-deadline' else 'end-date' end purpose,
            coalesce(sent.timezone, p.timezone) timezone, coalesce(a.nominal_target, private.reminder_target(coalesce(cy.action_deadline,cy.end_date),p.timezone)) target,
            coalesce(a.schedule_kind, j.schedule_kind) schedule_kind, coalesce(a.dispatch_target, j.dispatch_target) dispatch_target,
            j.state, j.reason, j.next_send_at, a.delivery, a.outcome,
            c.archived_at, cy.completed_at
        from public.credentials c join public.practices p on p.id = c.practice_id
        join lateral (select * from public.credential_cycles where practice_id = c.practice_id and credential_id = c.id order by cycle_number desc limit 1) cy on true
        left join lateral (select * from private.reminder_jobs where practice_id = c.practice_id and credential_id = c.id
            and cycle_id = cy.id and date_revision = cy.date_revision and invalidated_at is null
            and membership_id = settings.membership_id order by date_revision desc limit 1) j on true
        left join private.reminder_message_attempts a on a.cycle_id = cy.id and a.user_id = selected_user and a.channel = 'email'
        left join private.reminder_jobs sent on sent.id = a.job_id and sent.practice_id = c.practice_id
        where c.practice_id = p_practice_id and (p_after is null or c.id > p_after) order by c.id limit 100
    ) select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'cycleId',cycle_id,'dueDate',due,'datePurpose',purpose,
        'timezone',timezone,'target',target,'scheduleKind',schedule_kind,'dispatchTarget',dispatch_target,'nextSendAt',next_send_at,'state',coalesce(outcome,state,'pending'),
        'delivery',delivery,'reason',case when archived_at is not null then 'archived' when completed_at is not null then 'cycle-completed'
            when readiness <> 'ready' then readiness when due is null then 'missing-date' else reason end) order by id),'[]'::jsonb),
        (array_agg(id order by id desc))[1] into rows,last_id from page;
    select exists (select 1 from public.credentials where practice_id = p_practice_id and id > last_id) into has_more;
    select max(finished_at) into health from private.reminder_worker_runs where success;
    return jsonb_build_object('rows',rows,'nextCursor',case when has_more then last_id end,'emailReadiness',readiness,
        'smsOptional',true,'lastSuccessAt',health,
        'oldestDueAt',(select min(next_send_at) from private.reminder_jobs where practice_id = p_practice_id and state in ('queued','claimed')),
        'preference',private.get_my_email_reminder_preference(p_practice_id));
end;
$function$

CREATE OR REPLACE FUNCTION private.get_email_reminder_schedule_v3(p_practice_id uuid, p_namespace text, p_after uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
AS $function$
declare result jsonb; rows jsonb;
begin
    result:=private.get_email_reminder_schedule_v2(p_practice_id,p_namespace,p_after);
    select coalesce(jsonb_agg(item.value||jsonb_build_object('historyAvailable',true,
        'activeLinkAvailable',c.archived_at is null,'recovery',private.email_recovery_summary(a.id)) order by item.ordinality),'[]'::jsonb) into rows
    from jsonb_array_elements(result->'rows') with ordinality item(value,ordinality)
    join public.credentials c on c.id=(item.value->>'id')::uuid and c.practice_id=p_practice_id
    left join private.practice_reminder_settings s on s.practice_id=p_practice_id
    left join public.practice_memberships m on m.id=s.membership_id and m.practice_id=p_practice_id
    left join private.reminder_message_attempts a on a.cycle_id=(item.value->>'cycleId')::uuid and a.user_id=m.user_id;
    return jsonb_set(result,'{rows}',rows);
end;
$function$

CREATE OR REPLACE FUNCTION private.get_email_reminder_schedule_v4(p_practice_id uuid, p_namespace text, p_after uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
AS $function$
declare result jsonb; rows jsonb; authority private.gmail_reminder_authority; address text; blocked text;
begin
    result := private.get_email_reminder_schedule_v3(p_practice_id, p_namespace, p_after);
    select * into authority from private.gmail_reminder_authority where namespace = p_namespace;
    if found then
        select lower(trim(u.email)) into address from private.practice_reminder_settings s
            join public.practice_memberships m on m.id = s.membership_id and m.practice_id = s.practice_id
            join auth.users u on u.id = m.user_id where s.practice_id = p_practice_id;
        blocked := case when not authority.enabled then 'gmail-unavailable'
            when address is distinct from authority.allowed_recipient then 'gmail-recipient-blocked' end;
        if blocked is not null and result->>'emailReadiness' = 'ready' then
            result := jsonb_set(result, '{emailReadiness}', to_jsonb(blocked));
        end if;
    end if;
    select coalesce(jsonb_agg(item.value || jsonb_build_object('provider', private.reminder_provider_capability(a.id)) ||
        case when a.id is null and blocked is not null and item.value->>'reason' is null then jsonb_build_object('reason', blocked) else '{}'::jsonb end
        order by item.ordinality), '[]'::jsonb) into rows
    from jsonb_array_elements(result->'rows') with ordinality item(value, ordinality)
    left join private.practice_reminder_settings s on s.practice_id = p_practice_id
    left join public.practice_memberships m on m.id = s.membership_id and m.practice_id = p_practice_id
    left join private.reminder_message_attempts a on a.cycle_id = (item.value->>'cycleId')::uuid and a.user_id = m.user_id;
    return jsonb_set(result, '{rows}', rows);
end;
$function$

CREATE OR REPLACE FUNCTION private.get_email_reminder_timeline(p_practice_id uuid, p_attempt_id uuid, p_after jsonb DEFAULT NULL::jsonb, p_credential_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
AS $function$
declare rows jsonb; anchor record; last_row record; cursor jsonb;
begin
    perform private.require_recipient_member(p_practice_id,false);
    if not exists(select 1 from private.reminder_message_attempts where id=p_attempt_id and practice_id=p_practice_id) then return '{"status":"not-found"}'; end if;
    if p_credential_id is not null and not exists(select 1 from private.reminder_message_attempts a join private.reminder_jobs j on j.id=a.job_id and j.practice_id=a.practice_id where a.id=p_attempt_id and j.credential_id=p_credential_id and j.practice_id=p_practice_id) then return '{"status":"not-found"}'; end if;
    if p_after is not null then
        if jsonb_typeof(p_after)<>'object' or (select count(*) from jsonb_object_keys(p_after))<>3 or not(p_after ?& array['id','source','observedAt']) then return '{"status":"not-found"}'; end if;
        select * into anchor from private.email_reminder_timeline_rows(p_attempt_id)
            where id=(p_after->>'id')::uuid and source=p_after->>'source' and observed_at=(p_after->>'observedAt')::timestamptz;
        if not found then return '{"status":"not-found"}'; end if;
    end if;
    with page as(select * from private.email_reminder_timeline_rows(p_attempt_id)
        where p_after is null or (observed_at,source,id)<((p_after->>'observedAt')::timestamptz,p_after->>'source',(p_after->>'id')::uuid)
        order by observed_at desc,source desc,id desc limit 50)
    select coalesce(jsonb_agg(jsonb_build_object('id',id,'source',source,'observedAt',observed_at,'operation',operation,'anomaly',anomaly)
        order by observed_at desc,source desc,id desc),'[]'::jsonb) into rows from page;
    if jsonb_array_length(rows)=50 then
        cursor:=rows->49;cursor:=jsonb_build_object('id',cursor->>'id','source',cursor->>'source','observedAt',cursor->>'observedAt');
        if not exists(select 1 from private.email_reminder_timeline_rows(p_attempt_id) where (observed_at,source,id)<
            ((cursor->>'observedAt')::timestamptz,cursor->>'source',(cursor->>'id')::uuid)) then cursor:=null; end if;
    end if;
    return jsonb_build_object('status','success','rows',rows,'nextCursor',cursor);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then return '{"status":"not-found"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.get_email_reminder_timeline_v2(p_practice_id uuid, p_attempt_id uuid, p_after jsonb DEFAULT NULL::jsonb, p_credential_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
AS $function$
declare result jsonb;
begin
    result := private.get_email_reminder_timeline(p_practice_id, p_attempt_id, p_after, p_credential_id);
    if result->>'status' <> 'success' then return result; end if;
    return result || jsonb_build_object('provider', private.reminder_provider_capability(p_attempt_id));
end;
$function$

CREATE OR REPLACE FUNCTION private.get_my_email_reminder_preference(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pref private.reminder_email_preferences; can_edit boolean;
begin
    can_edit := private.require_recipient_member(p_practice_id, false);
    select * into pref from private.reminder_email_preferences where practice_id = p_practice_id and user_id = auth.uid();
    return jsonb_build_object('enabled', coalesce(pref.enabled, true), 'version', coalesce(pref.version, 1), 'canEnable', can_edit);
