CREATE OR REPLACE FUNCTION private.get_practice_reminder_recipient(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    can_edit boolean;
    settings private.practice_reminder_settings;
    selected jsonb;
    readiness text;
    result jsonb;
begin
    can_edit := private.require_recipient_member(p_practice_id, false);
    select * into settings from private.practice_reminder_settings where practice_id = p_practice_id;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    select pg_catalog.jsonb_build_object('id', m.id, 'email', u.email, 'role', m.role, 'state', m.state)
    into selected from public.practice_memberships m join auth.users u on u.id = m.user_id
    where m.practice_id = p_practice_id and m.id = settings.membership_id;
    readiness := case when settings.membership_id is null then 'no-recipient'
        when selected->>'state' = 'active' and selected->>'role' in ('administrator', 'manager')
            then 'sms-setup-pending' else 'member-unavailable' end;
    result := pg_catalog.jsonb_build_object('version', settings.version, 'selected', selected,
        'readiness', readiness, 'ready', false, 'canEdit', can_edit);
    if can_edit then
        result := result || pg_catalog.jsonb_build_object('candidates', coalesce((
            select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'id', m.id, 'email', u.email, 'role', m.role, 'state', m.state) order by m.created_at, m.id)
            from public.practice_memberships m join auth.users u on u.id = m.user_id
            where m.practice_id = p_practice_id and m.state = 'active'
                and m.role in ('administrator', 'manager')
        ), '[]'::jsonb));
    end if;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.get_practice_reminder_recipient_with_enrollment(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare recipient jsonb; enrollment jsonb; reason text;
begin
    recipient := private.get_practice_reminder_recipient(p_practice_id);
    reason := recipient->>'readiness';
    if reason = 'sms-setup-pending' then
        enrollment := private.sms_state(p_practice_id, (recipient->'selected'->>'id')::uuid);
        reason := enrollment->>'reason';
    end if;
    return pg_catalog.jsonb_build_object('recipient', recipient, 'enrollment',
        pg_catalog.jsonb_build_object('reason', reason, 'enrollmentReady', reason = 'enrolled', 'deliveryActive', false));
end;
$function$

CREATE OR REPLACE FUNCTION private.get_renewal_evidence(p_practice_id uuid, p_credential_id uuid, p_cycle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare credential public.credentials; cycle public.credential_cycles; files jsonb; notices jsonb;
begin
    perform private.require_register_member(p_practice_id, false);
    select * into credential from public.credentials where practice_id = p_practice_id and id = p_credential_id;
    select * into cycle from public.credential_cycles where practice_id = p_practice_id
        and credential_id = p_credential_id and id = p_cycle_id;
    if credential.id is null or cycle.id is null then return '{"status":"not-found"}'::jsonb; end if;
    select coalesce(jsonb_agg(private.evidence_projection(e, auth.uid()) order by e.created_at, e.id), '[]')
    into files from (select * from private.renewal_evidence where practice_id = p_practice_id
        and credential_id = p_credential_id and cycle_id = p_cycle_id and state in ('pending', 'available')
        order by created_at, id limit 20) e;
    select coalesce(jsonb_agg(private.evidence_projection(e, auth.uid()) order by e.updated_at desc, e.id), '[]')
    into notices from (select * from private.renewal_evidence where practice_id = p_practice_id
        and credential_id = p_credential_id and cycle_id = p_cycle_id and state in ('deleting', 'deleted', 'abandoned')
        order by updated_at desc, id limit 20) e;
    return jsonb_build_object('status', 'success', 'credentialId', credential.id,
        'cycleId', cycle.id, 'title', credential.title, 'archivedAt', credential.archived_at,
        'current', cycle.id = (private.current_credential_cycle(p_practice_id, p_credential_id)).id,
        'cycle', private.renewal_cycle_history(cycle, credential.type), 'files', files, 'notices', notices);
end;
$function$

CREATE OR REPLACE FUNCTION private.initialize_credential_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    insert into public.credential_cycles (practice_id, credential_id) values (new.practice_id, new.id);
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.invalidate_completed_email_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if new.completed_at is distinct from old.completed_at then
        perform private.dirty_email_reminders(new.practice_id, 'cycle-completed', new.credential_id);
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.invalidate_reminder_recipient(p_practice_id uuid, p_membership_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    settings private.practice_reminder_settings;
begin
    select * into settings from private.practice_reminder_settings
    where practice_id = p_practice_id for update;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    if settings.membership_id = p_membership_id then
        perform private.change_reminder_recipient(p_practice_id, null, p_reason);
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.invalidate_sms_enrollment(p_practice_id uuid, p_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare enrollment private.practice_sms_enrollments;
begin
    select * into enrollment from private.practice_sms_enrollments where practice_id=p_practice_id and membership_id=p_member_id for update;
    if not found then return; end if;
    update private.practice_sms_enrollments set consent_event_id=null,consent_epoch=null,verified_revision=null,verified_at=null,
        phone_revision=phone_revision+1,version=version+1,withdrawn=true where practice_id=p_practice_id and membership_id=p_member_id;
    update private.sms_verification_challenges set state='invalidated' where practice_id=p_practice_id and membership_id=p_member_id and state<>'invalidated';
    insert into private.sms_enrollment_events (practice_id,membership_id,actor_user_id,phone_revision,endpoint_id,kind)
        values (p_practice_id,p_member_id,auth.uid(),enrollment.phone_revision+1,enrollment.endpoint_id,'member-invalidated');
end;
$function$

CREATE OR REPLACE FUNCTION private.invitation_for_actor(p_token_digest text)
 RETURNS private.practice_invitations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result private.practice_invitations;
    actor_email text;
    latest_revocation timestamptz;
begin
    if p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$' then return null; end if;
    select email into actor_email from auth.users
    where id=auth.uid() and email_confirmed_at is not null;
    if actor_email is null then return null; end if;
    select * into result from private.practice_invitations where token_digest=p_token_digest;
    if not found then return null; end if;
    if result.email <> private.canonical_invitation_email(actor_email)
       or result.state='canceled' or pg_catalog.clock_timestamp() >= result.expires_at then return null; end if;
    select revoked_at into latest_revocation from public.practice_memberships
    where practice_id=result.practice_id and user_id=auth.uid();
    if result.state='pending' and latest_revocation is not null
       and result.issued_at <= latest_revocation then return null; end if;
    if result.state='accepted' and (result.accepted_user_id <> auth.uid()
       or not exists(select 1 from public.practice_memberships where practice_id=result.practice_id
                     and user_id=auth.uid() and state='active')) then return null; end if;
    return result;
exception when check_violation then return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.list_practice_register(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform private.require_register_member(p_practice_id, false);
    return pg_catalog.jsonb_build_object(
        'clinicians', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'id', id, 'name', name, 'version', version) order by created_at, id)
            from public.clinicians where practice_id = p_practice_id), '[]'::jsonb),
        'credentials', coalesce((select pg_catalog.jsonb_agg(
            private.credential_details_projection(c) order by c.created_at, c.id)
            from public.credentials c where c.practice_id = p_practice_id and c.archived_at is null), '[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION private.list_practice_register_with_maintenance(p_practice_id uuid, p_include_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform private.require_register_member(p_practice_id, false);
    if p_include_archived is null then return '{"status":"invalid"}'::jsonb; end if;
    return pg_catalog.jsonb_build_object(
        'clinicians', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'id', id, 'name', name, 'version', version) order by created_at, id)
            from public.clinicians where practice_id = p_practice_id), '[]'::jsonb),
        'credentials', coalesce((select pg_catalog.jsonb_agg(
            private.credential_maintenance_projection(c) || pg_catalog.jsonb_build_object(
                'suspected_duplicate_ids', private.credential_duplicate_ids(c)) order by c.created_at, c.id)
            from public.credentials c where c.practice_id = p_practice_id
                and (p_include_archived or c.archived_at is null)), '[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION private.list_practice_register_with_renewal(p_practice_id uuid, p_include_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; records jsonb;
begin
    perform private.require_register_member(p_practice_id, false);
    if p_include_archived is null then return '{"status":"invalid"}'::jsonb; end if;
    result := private.list_practice_register_with_maintenance(p_practice_id, p_include_archived);
    select coalesce(pg_catalog.jsonb_agg(item.value || pg_catalog.jsonb_build_object(
        'renewal', private.renewal_projection(c)) order by item.position), '[]'::jsonb) into records
    from pg_catalog.jsonb_array_elements(result->'credentials') with ordinality item(value, position)
    join public.credentials c on c.id = (item.value->>'id')::uuid and c.practice_id = p_practice_id;
    return pg_catalog.jsonb_set(result, '{credentials}', records);
end;
$function$

CREATE OR REPLACE FUNCTION private.lock_email_recipient(p_practice_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare recipient_user uuid;
begin
    perform 1 from public.practices where id = p_practice_id for update nowait;
    if not found then return false; end if;
    select m.user_id into recipient_user from private.practice_reminder_settings s
    join public.practice_memberships m on m.practice_id = s.practice_id and m.id = s.membership_id
    where s.practice_id = p_practice_id;
    if recipient_user is not null then
        perform 1 from auth.users where id = recipient_user for share nowait;
        perform 1 from private.reminder_email_account_state where user_id = recipient_user for update nowait;
    end if;
    return true;
exception when lock_not_available then return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.mutate_invitation(p_invitation_id uuid, p_expected_version integer, p_token_digest text, p_reissue boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result private.practice_invitations;
    issued timestamptz;
begin
    select * into result from private.practice_invitations where id=p_invitation_id;
    perform private.require_administrator(result.practice_id);
    select * into result from private.practice_invitations where id=p_invitation_id for update;
    if p_expected_version is null or p_expected_version < 1 then
        raise exception 'Invalid version' using errcode='23514';
    end if;
    if not p_reissue and result.state='canceled' then
        return pg_catalog.jsonb_build_object('status','success','invitation',private.invitation_projection(result));
    end if;
    if result.version <> p_expected_version or result.state <> 'pending' then
        return '{"status":"conflict"}'::jsonb;
    end if;
    issued := pg_catalog.clock_timestamp();
    if p_reissue then
        if p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$'
           or p_token_digest=result.token_digest then
            raise exception 'Invalid new digest' using errcode='23514';
        end if;
        update private.practice_invitations set token_digest=p_token_digest,
            issued_at=issued,expires_at=issued+interval '168 hours',version=version+1,updated_at=issued
        where id=p_invitation_id returning * into result;
    else
        update private.practice_invitations set state='canceled',version=version+1,updated_at=issued
        where id=p_invitation_id returning * into result;
    end if;
    return pg_catalog.jsonb_build_object('status','success','invitation',private.invitation_projection(result));
end;
$function$

CREATE OR REPLACE FUNCTION private.mutate_member(p_membership_id uuid, p_expected_version integer, p_role text, p_revoke boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    member public.practice_memberships;
begin
    select * into member from public.practice_memberships where id=p_membership_id;
    perform private.require_administrator(member.practice_id);
    select * into member from public.practice_memberships where id=p_membership_id for update;
    if p_expected_version is null or p_expected_version < 1 or
       (not p_revoke and (p_role is null or p_role not in ('administrator','manager','viewer'))) then
        raise exception 'Invalid member input' using errcode='23514';
    end if;
    if p_revoke and member.state='revoked' then return '{"status":"success"}'::jsonb; end if;
    if member.version <> p_expected_version or member.state <> 'active' then return '{"status":"conflict"}'::jsonb; end if;
    if member.role='administrator' and (p_revoke or p_role <> 'administrator')
       and (select count(*) from public.practice_memberships where practice_id=member.practice_id
            and role='administrator' and state='active') <= 1 then return '{"status":"last-administrator"}'::jsonb; end if;
    if not p_revoke and member.role=p_role then return '{"status":"success"}'::jsonb; end if;
    if p_revoke then
        update public.practice_memberships set state='revoked',revoked_at=pg_catalog.clock_timestamp(),
            version=version+1,updated_at=pg_catalog.clock_timestamp() where id=p_membership_id;
    else
        update public.practice_memberships set role=p_role,version=version+1,
            updated_at=pg_catalog.clock_timestamp() where id=p_membership_id;
    end if;
    if p_revoke or p_role = 'viewer' then
        perform private.invalidate_sms_enrollment(member.practice_id, p_membership_id);
        perform private.invalidate_reminder_recipient(member.practice_id, p_membership_id,
            case when p_revoke then 'revoked' else 'role-viewer' end);
    end if;
    return '{"status":"success"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_gmail_reminders(p_practice_id uuid, p_namespace text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET statement_timeout TO '5s'
 SET lock_timeout TO '1s'
AS $function$
declare authority private.gmail_reminder_authority; changed integer;
begin
    if not private.lock_email_recipient(p_practice_id) then return '{"status":"busy"}'; end if;
    select * into authority from private.gmail_reminder_authority where namespace = p_namespace for share nowait;
    if not found or authority.enabled or exists(select 1 from private.reminder_message_attempts where outcome = 'submitting') then
        return '{"status":"unavailable"}';
    end if;
    with canceled as (
        update private.reminder_jobs j set state = 'canceled', reason = 'provider-changed',
            claim_token = null, claim_until = null, invalidated_at = clock_timestamp(), updated_at = clock_timestamp()
        where j.practice_id = p_practice_id and j.state in ('blocked', 'queued', 'claimed')
            and not exists(select 1 from private.reminder_message_attempts a where a.cycle_id = j.cycle_id and a.user_id = j.user_id and a.channel = j.channel)
        returning practice_id, id
    ) insert into private.reminder_job_events(practice_id, job_id, operation)
        select practice_id, id, 'provider-changed' from canceled;
    get diagnostics changed = row_count;
    insert into private.reminder_reconcile_outbox(practice_id) values(p_practice_id)
    on conflict(practice_id) do update set generation = reminder_reconcile_outbox.generation + 1, cursor_id = null, updated_at = clock_timestamp();
    return jsonb_build_object('status', 'prepared', 'invalidated', changed);
exception when lock_not_available then return '{"status":"busy"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_my_sms_verification(p_practice_id uuid, p_request_id uuid, p_phone text, p_expected_version integer, p_change_confirmed boolean, p_otp_permission boolean, p_account_sid text, p_messaging_service_sid text, p_verify_service_sid text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    member uuid; endpoint private.sms_phone_endpoints; enrollment private.practice_sms_enrollments;
    challenge private.sms_verification_challenges; receipt private.sms_action_receipts; payload jsonb;
begin
    member := private.sms_member(p_practice_id, auth.uid(), true);
    if p_request_id is null or p_expected_version is null or p_expected_version < 1 or p_otp_permission is distinct from true
        or p_phone is null or p_phone !~ '^\+[1-9][0-9]{1,14}$' or p_verify_service_sid is null or p_verify_service_sid !~ '^VA[0-9a-fA-F]{32}$'
        or p_account_sid is null or p_account_sid !~ '^AC[0-9a-fA-F]{32}$'
        or p_messaging_service_sid is null or p_messaging_service_sid !~ '^MG[0-9a-fA-F]{32}$' then
        raise exception 'Invalid verification input' using errcode = '23514';
    end if;
    insert into private.sms_phone_endpoints (account_sid,messaging_service_sid,phone_e164)
    values (p_account_sid,p_messaging_service_sid,p_phone) on conflict do nothing;
    select * into endpoint from private.sms_phone_endpoints where account_sid = p_account_sid
        and messaging_service_sid = p_messaging_service_sid and phone_e164 = p_phone for update;
    payload := pg_catalog.jsonb_build_object('endpoint',endpoint.id,'version',p_expected_version,'confirmed',p_change_confirmed,'verifyService',p_verify_service_sid);
    select * into receipt from private.sms_action_receipts where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id;
    if found then
        if receipt.intent <> 'prepare' or receipt.payload <> payload then return private.sms_reply(p_practice_id,member,'conflict'); end if;
        return private.sms_reply(p_practice_id,member,'success');
    end if;
    if exists (select 1 from private.sms_verification_requests where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id) then
        return private.sms_reply(p_practice_id,member,'conflict');
    end if;
    select * into enrollment from private.practice_sms_enrollments where practice_id = p_practice_id and membership_id = member for update;
    if coalesce(enrollment.version,1) <> p_expected_version then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if endpoint.provider_blocked then return private.sms_reply(p_practice_id,member,'blocked'); end if;
    if enrollment.endpoint_id = endpoint.id and enrollment.verified_revision = enrollment.phone_revision then
        perform private.sms_receipt(p_practice_id,member,auth.uid(),p_request_id,'prepare',payload);
        return private.sms_reply(p_practice_id,member,'success');
    end if;
    if enrollment.endpoint_id is not null and enrollment.endpoint_id <> endpoint.id and p_change_confirmed is distinct from true then
        return private.sms_reply(p_practice_id,member,'confirmation-required');
    end if;
    -- Retire expired live challenges under their sole endpoint lock before successor allocation.
    update private.sms_verification_challenges set state = 'expired' where endpoint_id = endpoint.id
        and state in ('reserved','pending','uncertain') and expires_at <= pg_catalog.clock_timestamp();
    select * into challenge from private.sms_verification_challenges where endpoint_id = endpoint.id
        and state in ('reserved','pending','uncertain') for update;
    if found and (challenge.membership_id <> member or challenge.practice_id <> p_practice_id or challenge.state = 'uncertain') then
        return private.sms_reply(p_practice_id,member,'busy');
    end if;
    if not found then
        if enrollment.practice_id is null then
            insert into private.practice_sms_enrollments (practice_id,membership_id) values (p_practice_id,member);
        end if;
        if enrollment.endpoint_id is distinct from endpoint.id then
            update private.sms_verification_challenges set state = 'invalidated'
                where practice_id = p_practice_id and membership_id = member and state <> 'invalidated';
            update private.practice_sms_enrollments set endpoint_id = endpoint.id, phone_revision = phone_revision + 1,
                version = version + 1, verified_revision = null, verified_at = null, consent_event_id = null, consent_epoch = null, withdrawn = false
                where practice_id = p_practice_id and membership_id = member returning * into enrollment;
            insert into private.sms_enrollment_events (practice_id,membership_id,actor_user_id,phone_revision,endpoint_id,kind)
                values (p_practice_id,member,auth.uid(),enrollment.phone_revision,endpoint.id,'phone-change');
        else
            update private.practice_sms_enrollments set verified_revision = null, verified_at = null, consent_event_id = null, consent_epoch = null,
                withdrawn = false, version = version + 1 where practice_id = p_practice_id and membership_id = member returning * into enrollment;
        end if;
        insert into private.sms_verification_challenges (practice_id,membership_id,phone_revision,endpoint_id,verify_service_sid,state)
            values (p_practice_id,member,enrollment.phone_revision,endpoint.id,p_verify_service_sid,'reserved') returning * into challenge;
    elsif challenge.verify_service_sid <> p_verify_service_sid then return private.sms_reply(p_practice_id,member,'conflict');
    end if;
    insert into private.sms_enrollment_events (practice_id,membership_id,actor_user_id,phone_revision,endpoint_id,kind,disclosure_version,disclosure_text)
        values (p_practice_id,member,auth.uid(),challenge.phone_revision,endpoint.id,'otp-permission','e4-s1-v1',private.sms_disclosure('otp-permission',p_practice_id));
    insert into private.sms_verification_requests (actor_user_id,practice_id,membership_id,request_id,challenge_id,intent,payload)
        values (auth.uid(),p_practice_id,member,p_request_id,challenge.id,'send',payload);
    perform private.sms_receipt(p_practice_id,member,auth.uid(),p_request_id,'prepare',payload);
    return private.sms_reply(p_practice_id,member,'success');
end;
$function$

CREATE OR REPLACE FUNCTION private.preview_practice_invitation(p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    invitation private.practice_invitations;
    invited_role text;
begin
    invitation := private.invitation_for_actor(p_token_digest);
    if invitation.id is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    invited_role := invitation.role;
    if invitation.state='accepted' then
        select role into invited_role from public.practice_memberships
        where practice_id=invitation.practice_id and user_id=auth.uid() and state='active';
    end if;
    return pg_catalog.jsonb_build_object('status','success','name',
        (select name from public.practices where id=invitation.practice_id),
        'role',invited_role,'expires_at',invitation.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_gmail_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if tg_op = 'INSERT' then
        if exists(select 1 from private.reminder_message_attempts where provider_namespace = new.namespace) then
            raise exception 'Consumed provider namespace cannot be rebound';
        end if;
        return new;
    end if;
    if exists(select 1 from private.reminder_message_attempts where provider_namespace = old.namespace)
        and (tg_op = 'DELETE' or new.namespace is distinct from old.namespace
            or new.sender is distinct from old.sender or new.subject is distinct from old.subject) then
        raise exception 'Consumed Gmail namespace cannot be rebound';
    end if;
    if tg_op = 'UPDATE' and new is distinct from old then new.version := old.version + 1; end if;
    if tg_op = 'DELETE' then return old; end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.reconcile_email_reminders_at(p_namespace text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record; outbox private.reminder_reconcile_outbox; row record; context jsonb;
    endpoint private.reminder_email_endpoints; last_id uuid; scanned integer := 0; account_count integer; previous private.reminder_jobs; scheduled_job_id uuid; announce boolean;
begin
    if p_namespace is null or p_namespace !~ '^[a-zA-Z0-9_-]{1,80}$' then raise exception 'invalid namespace'; end if;
    account_count := 0;
    for candidate in select practice_id from private.reminder_reconcile_outbox order by updated_at, practice_id limit 10 loop
        if not private.lock_email_recipient(candidate.practice_id) then continue; end if;
        select * into outbox from private.reminder_reconcile_outbox where practice_id = candidate.practice_id;
        if not found then continue; end if;
        last_id := outbox.cursor_id;
        for row in select id from public.credentials where practice_id = candidate.practice_id
            and (outbox.cursor_id is null or id > outbox.cursor_id) order by id limit 100 loop
            scanned := scanned + 1;
            last_id := row.id;
            context := private.email_reminder_context(candidate.practice_id, row.id, p_namespace, p_now);
            if context is null then continue; end if;
            if context->>'email' is not null then
                insert into private.reminder_email_endpoints (provider_namespace, email)
                values (p_namespace, context->>'email') on conflict do nothing;
                select * into endpoint from private.reminder_email_endpoints
                where provider_namespace = p_namespace and email = context->>'email' for update nowait;
                context := private.email_reminder_context(candidate.practice_id, row.id, p_namespace, p_now);
            else endpoint := null; end if;
            select * into previous from private.reminder_jobs
            where cycle_id = (context->>'cycleId')::uuid and date_revision = (context->>'dateRevision')::integer
                and membership_id = (context->>'membershipId')::uuid and lead_days = 60 and channel = 'email';
            announce := context->>'scheduleKind' = 'catch-up' and context->>'reason' is null
                and (previous.id is null or previous.schedule_kind <> 'catch-up'
                    or previous.dispatch_target is distinct from (context->>'dispatchTarget')::timestamptz
                    or previous.selection_version is distinct from (context->>'selectionVersion')::integer
                    or previous.account_revision is distinct from (context->>'accountRevision')::bigint
                    or previous.preference_version is distinct from (context->>'preferenceVersion')::integer
                    or previous.timezone is distinct from context->>'timezone');
            insert into private.reminder_jobs (practice_id, credential_id, cycle_id, date_revision, membership_id,
                user_id, due_date, timezone, nominal_target, next_send_at, eligible_since, selection_version,
                account_revision, preference_version, endpoint_id, endpoint_epoch, schedule_kind, dispatch_target, state, reason)
            values (candidate.practice_id, row.id, (context->>'cycleId')::uuid, (context->>'dateRevision')::integer,
                (context->>'membershipId')::uuid, (context->>'userId')::uuid, (context->>'dueDate')::date,
                context->>'timezone', (context->>'target')::timestamptz, (context->>'nextSendAt')::timestamptz,
                (context->>'eligibleSince')::timestamptz, (context->>'selectionVersion')::integer,
                (context->>'accountRevision')::bigint, (context->>'preferenceVersion')::integer,
                endpoint.id, endpoint.epoch, context->>'scheduleKind', (context->>'dispatchTarget')::timestamptz, case when context->>'reason' is null then 'queued' else 'blocked' end, context->>'reason')
            on conflict (cycle_id, date_revision, membership_id, lead_days, channel) do update
            set due_date = excluded.due_date, timezone = excluded.timezone, nominal_target = excluded.nominal_target,
                next_send_at = excluded.next_send_at, eligible_since = excluded.eligible_since,
                schedule_kind = excluded.schedule_kind, dispatch_target = excluded.dispatch_target,
                selection_version = excluded.selection_version, account_revision = excluded.account_revision,
                preference_version = excluded.preference_version, endpoint_id = excluded.endpoint_id, endpoint_epoch = excluded.endpoint_epoch,
                state = excluded.state, reason = excluded.reason, claim_token = null, claim_until = null,
                invalidated_at = null, updated_at = p_now
            where reminder_jobs.state in ('blocked', 'queued', 'canceled')
                and not exists (select 1 from private.reminder_message_attempts a where a.cycle_id = excluded.cycle_id and a.user_id = excluded.user_id)
            returning id into scheduled_job_id;
            if scheduled_job_id is not null and announce then
                insert into private.reminder_job_events (practice_id, job_id, operation)
                values (candidate.practice_id, scheduled_job_id, 'catch-up-scheduled');
            end if;
        end loop;
        -- Domain mutations hold the same practice lock and reset this cursor/generation.
        if exists (select 1 from public.credentials where practice_id = candidate.practice_id and id > last_id) then
            update private.reminder_reconcile_outbox set cursor_id = last_id, updated_at = p_now where practice_id = candidate.practice_id and generation = outbox.generation;
        else
            delete from private.reminder_reconcile_outbox where practice_id = candidate.practice_id and generation = outbox.generation;
        end if;
        return jsonb_build_object('scanned', scanned, 'accounts', account_count);
    end loop;
    return jsonb_build_object('scanned', 0, 'accounts', account_count);
exception when lock_not_available then return jsonb_build_object('scanned', 0, 'accounts', 0, 'busy', true);
end;
$function$

CREATE OR REPLACE FUNCTION private.record_email_check_at(p_check_id uuid, p_token uuid, p_result jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r private.reminder_email_checks; a private.reminder_message_attempts; endpoint private.reminder_email_endpoints; status text;
begin
    if jsonb_typeof(p_result) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_result))<>3
        or not(p_result ?& array['matched','status','bounced']) or jsonb_typeof(p_result->'matched')<>'boolean'
        or jsonb_typeof(p_result->'bounced')<>'boolean' or (p_result->>'status' is not null and p_result->>'status' not in
            ('sent','delivered','delayed','failed','complained','suppressed')) then return '{"status":"invalid"}'; end if;
    select * into r from private.reminder_email_checks where id=p_check_id;
    if not found or r.token is distinct from p_token then return '{"status":"stale"}'; end if;
    select * into a from private.reminder_message_attempts where id=r.attempt_id;
    if r.result is not null then return '{"status":"recorded"}'; end if;
    status:=case when (p_result->>'matched')::boolean then p_result->>'status' end;
    select * into endpoint from private.reminder_email_endpoints where id=a.endpoint_id for update;
    if status in ('complained','suppressed') then
        perform id from private.reminder_jobs where endpoint_id=endpoint.id order by id for update;
    else perform 1 from private.reminder_jobs where id=a.job_id for update; end if;
    select * into a from private.reminder_message_attempts where id=a.id for update;
    select * into r from private.reminder_email_checks where id=p_check_id for update;
    if r.result is not null then return '{"status":"recorded"}'; end if;
    update private.reminder_email_checks set result=p_result,observed_at=p_now,
        anomaly=coalesce(a.delivery in ('delivered','bounced','complained','failed','suppressed') and status is not null and a.delivery<>status,false) where id=r.id;
    if status is not null then
        update private.reminder_message_attempts set outcome='accepted',delivery=private.email_delivery_state(delivery,status) where id=a.id;
        update private.reminder_jobs set state='accepted',updated_at=p_now where id=a.job_id and state in ('submitting','uncertain');
        if status in ('complained','suppressed') then
            update private.reminder_email_endpoints set suppressed=true,epoch=epoch+case when suppressed then 0 else 1 end,
                reason=case when reason='complained' then reason else status end where id=endpoint.id;
            update private.reminder_message_attempts set check_due=null,recovery_version=recovery_version+1
                where endpoint_id=endpoint.id and check_due is not null;
            with canceled as (update private.reminder_jobs set state='suppressed',reason='email-suppressed',claim_token=null,
                claim_until=null,invalidated_at=p_now,updated_at=p_now where endpoint_id=endpoint.id and state in ('blocked','queued','claimed') returning practice_id,id)
            insert into private.reminder_job_events(practice_id,job_id,operation) select practice_id,id,'email-suppressed' from canceled;
        end if;
    end if;

    update private.reminder_message_attempts set check_due=case when check_count<6 and private.email_check_open(reminder_message_attempts) then p_now+private.email_check_delay(check_count) end,
        recovery_version=recovery_version+1 where id=a.id;
    return '{"status":"recorded"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.record_email_reminder(p_attempt_id uuid, p_token uuid, p_outcome text, p_provider_id uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
 SET lock_timeout TO '1s'
AS $function$
declare attempt private.reminder_message_attempts;
begin
    if p_outcome is null or p_outcome not in ('accepted','failed','uncertain') or (p_outcome = 'accepted' and p_provider_id is null)
        or (p_outcome <> 'accepted' and p_provider_id is not null)
        or (p_error is not null and p_error not in ('provider-rejected','provider-unavailable','invalid-response','interrupted')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id;
    if not found or attempt.provider_kind <> 'resend' or attempt.token is distinct from p_token then return '{"status":"stale"}'::jsonb; end if;
    perform 1 from private.reminder_jobs where id = attempt.job_id for update;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id for update;
    if attempt.provider_id is not null and attempt.provider_id is distinct from p_provider_id and p_outcome = 'accepted' then
        return '{"status":"conflict"}'::jsonb;
    end if;
    if attempt.outcome in ('accepted','failed') then return '{"status":"recorded"}'::jsonb; end if;
    update private.reminder_message_attempts set outcome = p_outcome, provider_id = p_provider_id, error_category = p_error where id = attempt.id;
    update private.reminder_jobs set state = p_outcome, updated_at = clock_timestamp() where id = attempt.job_id and state in ('submitting','uncertain');
    return '{"status":"recorded"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.record_email_submission_at(p_submission_id uuid, p_token uuid, p_result jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r private.reminder_email_submissions; a private.reminder_message_attempts; j private.reminder_jobs; kind text; due timestamptz;
begin
    if jsonb_typeof(p_result) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_result))<>4
        or not(p_result ?& array['kind','providerId','errorCode','retryAfterSeconds'])
        or p_result->>'kind' is null or p_result->>'kind' not in ('accepted','rate-limited','permanent','uncertain')
        or (p_result->>'errorCode' is not null and p_result->>'errorCode' !~ '^[a-z0-9_-]{1,64}$')
        or (p_result->>'kind'='accepted') is distinct from (p_result->>'providerId' is not null)
        or (p_result->>'retryAfterSeconds' is not null and p_result->>'retryAfterSeconds' !~ '^[0-9]{1,10}$')
        or (p_result->>'retryAfterSeconds')::bigint > 2147483647
        or (p_result->>'kind'='rate-limited' and p_result->>'errorCode' is distinct from 'rate_limit_exceeded') then return '{"status":"invalid"}'; end if;
    select * into r from private.reminder_email_submissions where id=p_submission_id;
    if not found or r.token is distinct from p_token then return '{"status":"stale"}'; end if;
    select * into a from private.reminder_message_attempts where id=r.attempt_id;
    if a.provider_kind <> 'resend' then return '{"status":"stale"}'; end if;
    select * into j from private.reminder_jobs where id=a.job_id for update;
    select * into a from private.reminder_message_attempts where id=a.id for update;
    select * into r from private.reminder_email_submissions where id=r.id for update;
    if r.result is not null then
        if r.result->>'reason'='expired' and p_result->>'kind'='accepted' and a.outcome='uncertain' then
            perform private.record_email_reminder(a.id,a.token,'accepted',(p_result->>'providerId')::uuid,null);
            insert into private.reminder_job_events(practice_id,job_id,operation,occurred_at)
                values(a.practice_id,a.job_id,'late-acceptance-recorded',p_now);
        end if;
        return '{"status":"recorded"}';
    end if;
    update private.reminder_email_submissions set result=p_result,observed_at=p_now where id=r.id;
    if a.outcome='accepted' then return '{"status":"recorded"}'; end if;
    kind:=p_result->>'kind';
    if kind='rate-limited' then
        due:=private.reminder_next_window(p_now,j.timezone,p_now+greatest(
            case when r.ordinal=1 then interval '1 minute' else interval '5 minutes' end,
            coalesce((p_result->>'retryAfterSeconds')::integer,0)*interval '1 second'));
        update private.reminder_message_attempts set outcome='uncertain',
            recovery_state=case when post_count>=3 then 'exhausted' when due+interval '30 seconds'>=retry_expires then 'expired'
                when j.invalidated_at is not null then 'canceled' else 'retry-pending' end,
            retry_due=case when post_count<3 and due+interval '30 seconds'<retry_expires and j.invalidated_at is null then due end,
            recovery_version=recovery_version+1 where id=a.id;
    else
        update private.reminder_message_attempts set outcome=case kind when 'accepted' then 'accepted' when 'permanent' then 'failed' else 'uncertain' end,
            provider_id=case when kind='accepted' then (p_result->>'providerId')::uuid else provider_id end,
            recovery_state=kind,retry_due=null,recovery_version=recovery_version+1,
            check_due=case when kind='accepted' and check_count=0 then p_now+interval '5 minutes' else check_due end where id=a.id;
    end if;
    update private.reminder_jobs set state=case kind when 'accepted' then 'accepted' when 'permanent' then 'failed' else 'uncertain' end,
        updated_at=p_now where id=j.id and state in ('submitting','uncertain');
    return '{"status":"recorded"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.record_gmail_reminder_at(p_attempt_id uuid, p_token uuid, p_outcome text, p_message_id text, p_error text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare attempt private.reminder_message_attempts; result jsonb;
begin
    if p_outcome is null or p_outcome not in ('accepted', 'failed', 'uncertain')
        or (p_outcome = 'accepted') is distinct from (p_message_id is not null)
        or (p_message_id is not null and p_message_id !~ '^[a-zA-Z0-9_-]{1,128}$')
        or (p_error is not null and p_error not in ('provider-rejected', 'provider-unavailable', 'invalid-response', 'interrupted'))
        or (p_outcome = 'accepted' and p_error is not null) then return '{"status":"invalid"}'; end if;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id;
    if not found or attempt.provider_kind <> 'gmail' or attempt.token is distinct from p_token then return '{"status":"stale"}'; end if;
    perform 1 from private.reminder_jobs where id = attempt.job_id for update;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id for update;
    result := jsonb_build_object('outcome', p_outcome, 'messageId', p_message_id, 'error', p_error);
    if attempt.gmail_result is not null then
        if attempt.gmail_result = result then return '{"status":"recorded"}'; end if;
        return '{"status":"conflict"}';
    end if;
    update private.reminder_message_attempts set outcome = p_outcome, gmail_message_id = p_message_id,
        error_category = p_error, gmail_result = result where id = attempt.id;
    update private.reminder_jobs set state = p_outcome, updated_at = p_now where id = attempt.job_id;
    insert into private.reminder_job_events(practice_id, job_id, operation, occurred_at)
        values(attempt.practice_id, attempt.job_id, 'gmail-result-' || p_outcome, p_now);
    return '{"status":"recorded"}';
exception when unique_violation then return '{"status":"conflict"}';
end;
$function$

CREATE OR REPLACE FUNCTION private.record_renewal_evidence_cleanup(p_object_id uuid, p_token uuid, p_purged boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence private.renewal_evidence; object private.renewal_evidence_objects;
begin
    select * into object from private.renewal_evidence_objects where id = p_object_id;
    if not found then return false; end if;
    select * into evidence from private.renewal_evidence where id = object.evidence_id;
    perform 1 from public.practices where id = evidence.practice_id for update;
    select * into object from private.renewal_evidence_objects where id = p_object_id;
    if p_token is null or object.claim_token is distinct from p_token or object.claim_until <= clock_timestamp()
        or evidence.state not in ('deleting', 'deleted', 'abandoned') or p_purged is null then return false; end if;
    update private.renewal_evidence_objects set state = case when p_purged then 'purged' else 'purging' end,
        claim_token = null, claim_until = null,
        failures = case when p_purged then 0 else least(failures + 1, 16) end,
        next_check_at = clock_timestamp() + case when p_purged then interval '24 hours'
            else interval '1 minute' * least(60, power(2, least(failures, 6))) end,
        updated_at = clock_timestamp() where id = object.id;
    if p_purged and evidence.charged then
        update private.renewal_evidence set state = case when state = 'deleting' then 'deleted' else state end,
            filename = null, charged = false, updated_at = clock_timestamp() where id = evidence.id;
        perform private.evidence_event(evidence, null, 'purge-completed');
    end if;
    return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.record_renewal_evidence_download(p_access_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare access_event private.renewal_evidence_audit_events; evidence private.renewal_evidence;
begin
    select * into access_event from private.renewal_evidence_audit_events
    where id = p_access_id and operation = 'download-authorized';
    if not found then return false; end if;
