CREATE OR REPLACE FUNCTION private.reminder_target(p_date date, p_timezone text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare local_target timestamp; target timestamptz;
begin
    if p_date is null or p_date < date '0001-03-02' or p_date > date '9999-12-31' then return null; end if;
    local_target := p_date - 60 + time '09:00';
    target := local_target at time zone p_timezone;
    if target at time zone p_timezone <> local_target then return null; end if;
    return target;
end;
$function$

CREATE OR REPLACE FUNCTION private.reminder_valid_window(p_target timestamp with time zone, p_zone text, p_now timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare anchor timestamptz; local_anchor timestamp; day date; local_candidate timestamp;
    candidate timestamptz; offset_day integer;
begin
    if p_target is null or p_now is null then return null; end if;
    anchor := greatest(p_target, p_now);
    local_anchor := anchor at time zone p_zone;
    if local_anchor::date < date '0001-01-01' or local_anchor::date > date '9999-12-31' then return null; end if;
    if local_anchor::time >= time '09:00' and local_anchor::time < time '17:00' then return anchor; end if;
    day := local_anchor::date + case when local_anchor::time >= time '17:00' then 1 else 0 end;
    for offset_day in 0..7 loop
        if day + offset_day > date '9999-12-31' then return null; end if;
        local_candidate := day + offset_day + time '09:00';
        candidate := local_candidate at time zone p_zone;
        if candidate >= anchor and candidate at time zone p_zone = local_candidate then return candidate; end if;
    end loop;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.remove_renewal_evidence(p_practice_id uuid, p_credential_id uuid, p_cycle_id uuid, p_evidence_id uuid, p_request_id uuid, p_expected_version integer, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence private.renewal_evidence; receipt private.renewal_evidence_requests; payload jsonb; result jsonb;
begin
    perform private.require_register_member(p_practice_id, true);
    if p_request_id is null or p_expected_version is null or p_expected_version < 1
        or p_confirmed is distinct from true then return '{"status":"invalid"}'::jsonb; end if;
    payload := jsonb_build_object('credentialId', p_credential_id, 'cycleId', p_cycle_id,
        'evidenceId', p_evidence_id, 'expectedVersion', p_expected_version, 'confirmed', true);
    select * into receipt from private.renewal_evidence_requests where practice_id = p_practice_id
        and actor_user_id = auth.uid() and request_id = p_request_id;
    if found then
        if receipt.operation <> 'remove' or receipt.payload <> payload then return '{"status":"request-conflict"}'::jsonb; end if;
        select * into evidence from private.renewal_evidence where id = receipt.evidence_id;
        return jsonb_build_object('status', 'success', 'evidenceId', evidence.id, 'state', evidence.state);
    end if;
    select * into evidence from private.renewal_evidence where practice_id = p_practice_id
        and credential_id = p_credential_id and cycle_id = p_cycle_id and id = p_evidence_id;
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    if evidence.version <> p_expected_version or evidence.version = 2147483647
        or evidence.state not in ('pending', 'available') then return '{"status":"conflict"}'::jsonb; end if;
    update private.renewal_evidence set state = 'deleting', version = version + 1, updated_at = clock_timestamp()
    where id = evidence.id returning * into evidence;
    update private.renewal_evidence_objects set state = 'purging', next_check_at = clock_timestamp()
    where evidence_id = evidence.id;
    perform private.evidence_event(evidence, auth.uid(), 'delete-requested');
    result := jsonb_build_object('status', 'success', 'evidenceId', evidence.id, 'state', evidence.state);
    insert into private.renewal_evidence_requests (practice_id, actor_user_id, request_id, evidence_id, operation, payload, result)
    values (p_practice_id, auth.uid(), p_request_id, evidence.id, 'remove', payload, result);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.renewal_projection(p_record credentials)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare cycle public.credential_cycles; link private.credential_renewal_links;
    workflow private.credential_renewal_workflows;
begin
    cycle := private.current_credential_cycle(p_record.practice_id, p_record.id);
    select * into link from private.credential_renewal_links
    where practice_id = p_record.practice_id and credential_id = p_record.id;
    select * into workflow from private.credential_renewal_workflows
    where practice_id = p_record.practice_id and cycle_id = cycle.id;
    return pg_catalog.jsonb_build_object('link', pg_catalog.jsonb_build_object('url', link.url,
        'version', coalesce(link.version, 1)), 'workflow', pg_catalog.jsonb_build_object(
        'cycleId', cycle.id, 'status', coalesce(workflow.status, 'not-started'),
        'version', coalesce(workflow.version, 1), 'acknowledgedAt', workflow.acknowledged_at));
end;
$function$

CREATE OR REPLACE FUNCTION private.renewal_url(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare normalized text; parts text[]; hostname text; suffix text; label text;
begin
    normalized := nullif(private.register_name(p_value), '');
    if normalized is null then return null; end if;
    parts := pg_catalog.regexp_match(normalized, '^https://([^/?#]+)(.*)$', 'i');
    if char_length(normalized) > 2048 or parts is null then
        raise exception 'invalid renewal URL' using errcode = '22023';
    end if;
    hostname := parts[1]; suffix := parts[2];
    if char_length(hostname) > 253
        or hostname !~ '^[a-zA-Z0-9-]+([.][a-zA-Z0-9-]+)+$'
        or hostname ~* '[.]([0-9]+|0x[0-9a-f]+)$'
        or suffix !~ '^([a-zA-Z0-9._~!$&()*+,;=:@/?#-]|%[0-9a-fA-F]{2})*$'
        or char_length(suffix) - char_length(pg_catalog.replace(suffix, '#', '')) > 1 then
        raise exception 'invalid renewal URL' using errcode = '22023';
    end if;
    foreach label in array pg_catalog.string_to_array(hostname, '.') loop
        if char_length(label) > 63 or label !~ '^[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?$' then
            raise exception 'invalid renewal URL' using errcode = '22023';
        end if;
    end loop;
    return 'https://' || pg_catalog.substring(normalized, 9);
end;
$function$

CREATE OR REPLACE FUNCTION private.request_email_reminder_check(p_practice_id uuid, p_attempt_id uuid, p_request_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
 SET lock_timeout TO '1s'
AS $function$
declare a private.reminder_message_attempts; receipt private.reminder_email_check_requests; result jsonb; now timestamptz:=clock_timestamp();
begin
    perform private.require_recipient_member(p_practice_id,true);
    select * into a from private.reminder_message_attempts where id=p_attempt_id and practice_id=p_practice_id;
    if not found then return '{"status":"not-found"}'; end if;
    perform 1 from private.reminder_jobs where id=a.job_id for update;
    select * into a from private.reminder_message_attempts where id=p_attempt_id for update;
    select * into receipt from private.reminder_email_check_requests where practice_id=p_practice_id and request_id=p_request_id;
    if found then
        if receipt.attempt_id<>p_attempt_id or receipt.actor_user_id<>auth.uid() or receipt.expected_version<>p_expected_version then
            return '{"status":"request-conflict"}'; end if;
        return receipt.result;
    end if;
    result:=case when p_request_id is null or p_expected_version is null then '{"status":"invalid"}'::jsonb
        when a.recovery_version<>p_expected_version then '{"status":"conflict"}'::jsonb
        when a.provider_id is null then '{"status":"unknown-id"}'::jsonb
        when not private.email_check_open(a) then '{"status":"complete"}'::jsonb
        when a.check_count>=6 then '{"status":"exhausted"}'::jsonb
        when (a.last_check_reserved is not null and a.last_check_reserved>now-interval '15 minutes')
            or exists(select 1 from private.reminder_email_checks r where r.attempt_id=a.id and r.result is null)
            or a.check_due<=now then '{"status":"cooldown"}'::jsonb
        else '{"status":"queued"}'::jsonb end;
    if result->>'status'='queued' then
        update private.reminder_message_attempts set check_due=now,recovery_version=recovery_version+1 where id=a.id;
    end if;
    if p_request_id is not null and p_expected_version is not null then
        insert into private.reminder_email_check_requests values(p_practice_id,p_request_id,p_attempt_id,auth.uid(),p_expected_version,result,now);
    end if;
    return result;
end;
$function$

